const PREGUNTAS = [
{"b": "t1", "pr": false, "q": "En el diseño del hardware de red, ¿qué tecnologías de transmisión se usan mucho en la actualidad? (Elija dos)", "o": ["Estrella", "Difusión", "Punto a punto", "Símplex", "Banda angosta"], "c": [1, 2], "why": "Según la tecnología de transmisión, las redes son de difusión (un canal compartido que todos escuchan) o punto a punto (enlaces entre pares de equipos). Ojo: Estrella es una topología física y símplex es una direccionalidad: son otras formas de clasificar las redes.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "Ordene las redes de menor a mayor cobertura.", "o": ["Internet, WAN, MAN, LAN y PAN", "PAN, SAN, LAN, MAN y WAN", "PAN, LAN, WAN, MAN e Internet", "PAN, LAN, MAN, WAN e Internet", "LAN, PAN, MAN, WAN e Internet"], "c": [3], "why": "PAN cubre el entorno de una persona; LAN, un edificio o campus; MAN, una ciudad; WAN, un país o continente. Internet une redes de todo el mundo. Ojo: SAN (red de almacenamiento) no es una categoría por cobertura; y el orden de Internet a PAN es de mayor a menor.", "src": "Teóricas 1.er parcial · Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "Cuando usamos una conexión por Bluetooth, ¿de qué tipo de red hablamos?", "o": ["LAN", "MAN", "PAN", "WAN", "WMAN"], "c": [2], "why": "Bluetooth (IEEE 802.15) arma pequeñas redes personales inalámbricas (WPAN) de corto alcance, de pocos metros. Ojo: Que sea inalámbrica no la vuelve LAN: su alcance es el entorno de una persona.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "¿Dónde encontraríamos las redes por cableado eléctrico?", "o": ["PAN", "LAN", "WAN", "Internet"], "c": [1], "why": "Usan los cables de electricidad que ya hay en una casa u oficina para armar la red local de ese lugar. Ojo: No llegan a cubrir un país o continente: el alcance es el del cableado del edificio.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "La red del campus de la UTN Facultad Regional Córdoba es una red MAN.", "o": ["Verdadero", "Falso"], "c": [1], "why": "Un campus de una sola organización es una LAN, aunque tenga varios edificios. Una MAN cubre una ciudad. Ojo: Que el campus sea grande no lo convierte en MAN.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "La tecnología IEEE 802.16 se puede clasificar como una red…", "o": ["LAN cableada", "WPAN", "WMAN", "WLAN"], "c": [2], "why": "WiMax (802.16) es inalámbrica y cubre distancias de hasta unos 70 km: alcance metropolitano, o sea, WMAN. Ojo: WLAN es 802.11 (Wi-Fi), con alcance de un edificio o campus.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "Una persona vive en un pueblo y tiene su campo a 50 km. Quiere controlar sus instalaciones por Internet. ¿Qué tecnología tendría que contratar?", "o": ["IEEE 802.15", "IEEE 802.5", "IEEE 802.16", "IEEE 802.3", "IEEE 802.11"], "c": [2], "why": "WiMax (802.16) está pensada para dar Internet inalámbrica en zonas rurales, a decenas de kilómetros (hasta unos 70 km). Ojo: 802.11 (Wi-Fi) llega a decenas de metros en uso normal, muy lejos de 50 km.", "src": "Teóricas 1.er parcial · Forms PDF 3 · Forms preguntero 1.er parcial · Lista que pasaste (23/11) (preguntero web)"},
{"b": "t1", "pr": false, "q": "Una WLAN es una red: (seleccione tres)", "o": ["De difusión", "Ofrece un ancho de banda fijo a cada uno de los host conectados", "Inalámbrica", "Símplex", "El ancho de banda total se divide en partes iguales entre los dispositivos conectados", "Utiliza el protocolo CSMA/CA", "Full dúplex", "WAN"], "c": [0, 2, 5], "why": "En una WLAN todos comparten el mismo aire: es inalámbrica y de difusión. Como una estación no puede detectar colisiones mientras transmite, las evita con CSMA/CA. Ojo: No es full dúplex: en un mismo canal de radio no se puede transmitir y escuchar a la vez.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "Wi-Fi es una red de:", "o": ["Banda ancha, semidúplex, LAN", "Banda angosta, full dúplex, LAN", "Banda ancha, full dúplex, MAN", "Banda angosta, símplex, PAN", "Banda ancha, símplex, WAN"], "c": [0], "why": "Wi-Fi da altas velocidades (banda ancha) y cubre un edificio (LAN). Es semidúplex porque en un canal de radio no se puede transmitir y recibir al mismo tiempo. Ojo: Full dúplex lo logra un switch con cable, donde cada sentido tiene su par de hilos; en el aire no.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "Identifique las tecnologías de LAN: red empresarial implementada con tecnología cableada / red de campus universitario implementada con tecnología inalámbrica.", "o": ["Cableada: Token Ring · Campus inalámbrico: Bluetooth", "Cableada: Ethernet · Campus inalámbrico: Wi-Fi", "Cableada: Ethernet · Campus inalámbrico: Wi-Max", "Cableada: Wi-Fi · Campus inalámbrico: Ethernet", "Cableada: Wi-Max · Campus inalámbrico: Wi-Fi"], "c": [1], "why": "Ethernet (802.3) es la tecnología de LAN cableada y Wi-Fi (802.11) la de LAN inalámbrica. Un campus, aunque sea grande, es una LAN. Ojo: Wi-Max (802.16) es inalámbrica pero metropolitana (WMAN), no una LAN de campus.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "Si tuviera que implementar una red de computadoras temporaria de manera rápida y económica, lo haría con tecnología:", "o": ["Wi-Fi", "3G", "Telefónica", "Ethernet", "Frame Relay"], "c": [0], "why": "Con Wi-Fi no hay que tender cables: se instala un access point y los equipos se conectan por radio. Por eso se monta rápido y es barata. Ojo: Ethernet exige tender y certificar cableado, lo que lleva tiempo y dinero.", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t1", "pr": false, "q": "Debe intercambiar datos entre un teléfono celular y una PC que tiene placas de red Ethernet y Wi-Fi. En la oficina no hay conexión a Internet. ¿Por dónde podría hacerlo? (Elija dos)", "o": ["Un switch", "Cable de red cruzado", "Wi-Fi", "Bluetooth", "Ethernet"], "c": [2, 3], "why": "El celular no tiene puerto de red cableado: sus radios son Wi-Fi y Bluetooth. Las dos permiten una conexión directa entre equipos cercanos sin pasar por Internet. Ojo: Cable cruzado, switch y Ethernet necesitan un puerto RJ-45, que el celular no tiene.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "Si tuviera que elegir un tipo de red que le brindara garantía de entrega de los mensajes sin demora (en tiempo real), en orden y con un ancho de banda constante, elegiría:", "o": ["Red conmutada por etiquetas", "Red conmutada por mensajes", "Red conmutada por paquetes", "Red conmutada por circuitos", "Red por difusión"], "c": [3], "why": "La conmutación de circuitos reserva un camino fijo de punta a punta durante toda la comunicación, como una llamada telefónica clásica. Ese camino reservado da ancho de banda constante, orden y ninguna espera en colas. Ojo: En la conmutación de paquetes los enlaces se comparten: los paquetes pueden demorarse en colas o llegar desordenados.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "En las aplicaciones de negocios, ¿cómo se llama el modelo con el que interactúan los dispositivos?", "o": ["Igual a igual (peer-to-peer)", "Comercio electrónico", "Modelo de referencia OSI", "Cliente-servidor"], "c": [3], "why": "En una empresa la información está en servidores y los empleados acceden desde sus equipos (clientes): el cliente pide y el servidor responde. Ojo: Igual a igual es el modelo típico de la comunicación entre personas en el hogar, sin servidor central.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "En las aplicaciones domésticas en las que las personas se comunican entre sí sin un servidor central (por ejemplo, para compartir archivos), ¿cómo se llama el modelo de interacción?", "o": ["Cliente-servidor", "Igual a igual (peer-to-peer)", "Modelo de referencia OSI", "Conmutación de circuitos"], "c": [1], "why": "En el modelo igual a igual no hay un servidor fijo: cada equipo puede pedir y ofrecer información a los demás. Ojo: Cliente-servidor sirve para acceder a información remota guardada en un servidor; acá no hay servidor central.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "Al usar redes de computadoras encontramos distintos usos o aplicaciones. ¿Cuáles de estos son categorías de uso de las redes? (Elija dos)", "o": ["Usuarios móviles", "Conmutación de circuitos", "Aplicaciones de negocios", "Control de acceso al medio", "Topología en estrella"], "c": [0, 2], "why": "Los usos de las redes se agrupan en aplicaciones de negocios, aplicaciones domésticas y usuarios móviles. Ojo: Topología, acceso al medio y conmutación son aspectos técnicos de cómo funciona la red, no usos.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "Si una estación de trabajo se encuentra a 180 m del armario principal de la red:", "o": ["Podré empalmar dos cables UTP de largo normalizado (90 m)", "Podré colocar un switch en un punto intermedio para repetir la señal", "Deberé ubicar a la estación de trabajo en otra VLAN", "Reemplazaré el cable UTP por coaxil para conectar la PC al switch"], "c": [1], "why": "Un tramo de UTP llega a 100 m. Un switch en el medio regenera la señal y arranca un tramo nuevo, así se cubren los 180 m. Ojo: Empalmar dos cables no regenera la señal: sigue siendo un solo tramo de 180 m, fuera de norma.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "Cuál de las siguientes clasificaciones de redes es decreciente con respecto al área de cobertura", "o": ["WAN - MAN - LAN - PAN", "MAN - WAN - LAN - PAN", "LAN - MAN - WAN - PAN", "PAN - LAN - MAN - WAN", "WAN - SAN - MAN - LAN"], "c": [0], "why": "De mayor a menor cobertura: WAN (país o continente), MAN (ciudad), LAN (edificio o campus) y PAN (alrededor de una persona). La opción con SAN es trampa: una SAN es una red de almacenamiento, no un escalón de cobertura.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t1", "pr": false, "q": "¿Cuáles son ventajas de la conmutación de paquetes frente a la conmutación de circuitos? (elegí dos)", "o": ["Se aprovecha mejor el ancho de banda", "Cada paquete se encamina de manera independiente y puede seguir rutas distintas", "Garantiza un ancho de banda constante durante la comunicación", "Se establece un camino dedicado antes de transmitir", "Los paquetes llegan siempre en orden y sin demora"], "c": [0, 1], "why": "En paquetes el enlace se comparte: nadie reserva capacidad que no usa, y si un camino falla cada paquete busca otro (por eso Internet es tolerante a fallas). Ojo: el camino dedicado y el ancho de banda garantizado son de la conmutación de circuitos (la telefonía clásica).", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t1", "pr": false, "q": "Una red donde todos los dispositivos comparten un canal de comunicación y es necesario un esquema de direcciones para distinguir uno del otro es una red:", "o": ["Difusión", "De banda angosta", "Punto a punto", "Simplex", "Pública"], "c": [0], "why": "En una red de difusión hay un solo canal compartido: todos reciben lo que se envía, y cada equipo mira la dirección de destino para saber si es para él. En punto a punto, en cambio, cada enlace une solo dos equipos.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t1", "q": "Cuando utilizamos las redes de computadoras, encontramos distintos tipos de usos o aplicaciones para las mismas (elija dos):", "o": ["Usuarios fijos", "Aplicaciones de negocios", "Redes de conmutación", "Usuarios móviles", "Aplicaciones domésticas"], "c": [1, 4], "why": "Tanenbaum y la filmina 1-01 clasifican los usos en aplicaciones de negocios y aplicaciones domésticas (además de usuarios móviles). El preguntero marcó negocios + domésticas.", "nota": "El preguntero del zip anotó 'Usuarios fijos' y 'Aplicaciones de negocios'. Según la filmina, los usos son negocios, domésticos y usuarios móviles; 'usuarios fijos' no figura. Si te aparece, priorizá negocios y domésticas.", "src": "Preguntero 1er parcial (zip) / Filmina 1-01", "pr": false},
{"b": "t2", "pr": false, "q": "¿A qué denominamos interfaz en una arquitectura de protocolos?", "o": ["Es el conjunto de capas y protocolos de una red", "Es el medio físico (cable o radio) que une dos equipos", "Es el conjunto de reglas con que se comunican capas del mismo nivel en equipos distintos", "Define las operaciones y servicios primitivos que la capa de abajo pone a disposición de la capa inmediata superior"], "c": [3], "why": "Entre capas vecinas de un mismo equipo hay una interfaz: indica qué servicios ofrece la capa de abajo a la de arriba y cómo pedirlos. Ojo: Las reglas entre capas del mismo nivel en equipos distintos son el protocolo, no la interfaz.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "¿Cómo se lleva a cabo la comunicación virtual entre las capas del mismo nivel en una arquitectura de protocolos?", "o": ["Descendente", "Vertical", "Horizontal", "Ascendente"], "c": [2], "why": "La capa N de un equipo se comunica con la capa N del otro mediante el protocolo de capa N (capas homólogas). Esa comunicación virtual se dibuja horizontal. Ojo: Vertical es la comunicación real entre capas vecinas del mismo equipo: bajando al encapsular y subiendo al desencapsular.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "¿Qué capa del modelo TCP/IP permite que los hosts inyecten paquetes en cualquier red y que viajen de manera independiente hacia el destino?", "o": ["Interred", "Transporte", "Aplicación", "Host a red"], "c": [0], "why": "La capa de interred direcciona y encamina: cada paquete busca su camino por su cuenta, aun atravesando redes distintas, hasta llegar al destino. Ojo: Transporte trabaja de extremo a extremo entre hosts y no decide el camino entre redes.", "src": "Teóricas 1.er parcial · Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "¿Qué capa del modelo TCP/IP recibe los paquetes, los encapsula y los entrega a dispositivos de la misma red?", "o": ["Interred", "Host a red", "Aplicación", "Transporte"], "c": [1], "why": "La capa host a red (acceso a la red) arma la trama con el paquete adentro y la pone en el medio para entregarla a otro equipo de la misma red. Ojo: Interred lleva el paquete entre redes distintas; la entrega dentro de una misma red es tarea de host a red.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "¿Qué protocolos encontramos en la capa de aplicación del modelo TCP/IP? (Elija dos)", "o": ["SMTP", "UDP", "IP", "TELNET", "TCP"], "c": [0, 3], "why": "SMTP (envío de correo) y TELNET (acceso remoto) son servicios que usan directamente las aplicaciones del usuario. Ojo: TCP y UDP son de transporte, e IP es de interred.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "¿Qué protocolos se encuentran en la capa de transporte del modelo TCP/IP?", "o": ["IP e ICMP", "HTTP y SMTP", "TCP y UDP", "Ethernet y Wi-Fi"], "c": [2], "why": "TCP (orientado a conexión y fiable) y UDP (sin conexión) llevan los datos de extremo a extremo entre procesos de los hosts. Ojo: IP e ICMP son de interred: mueven paquetes entre redes, no entre procesos.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Teóricas 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "¿Cuál es la secuencia de encapsulamiento en el equipo origen?", "o": ["Bits, tramas, paquetes, segmentos, datos", "Datos, segmentos, paquetes, tramas, bits", "Datos, segmentos, tramas, paquetes, bits", "Datos, paquetes, segmentos, tramas, bits"], "c": [1], "why": "Al bajar por las capas, cada una envuelve lo que recibe de arriba: transporte arma segmentos, interred paquetes, host a red tramas, y al final salen bits por el medio. Ojo: De bits a datos es el orden del destino (desencapsulamiento), no del origen.", "src": "Teóricas 1.er parcial · Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "Una trama Ethernet contiene en su carga útil:", "o": ["Solo los datos de aplicación", "Cabecera de enlace, cabecera de red y datos de aplicación", "Cabecera de red, cabecera de transporte y datos de aplicación", "Cabecera de transporte y datos de aplicación, sin cabecera de red"], "c": [2], "why": "La trama envuelve al paquete IP, que envuelve al segmento, que envuelve a los datos. Todo el paquete, con sus cabeceras, viaja como carga útil de la trama. Ojo: La cabecera de enlace (MAC y tipo) es la de la propia trama: va por fuera de la carga útil, no adentro.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "¿En qué capa del modelo OSI trabaja un switch?", "o": ["Transporte", "Red", "Física", "Enlace de datos"], "c": [3], "why": "El switch decide por qué puerto reenviar cada trama mirando la dirección MAC destino, que es información de la capa de enlace. Ojo: El que trabaja solo en la capa física, repitiendo bits, es el hub.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "¿En qué capa trabaja la placa de red?", "o": ["En la capa física y en la subcapa MAC de la capa de enlace", "Solo en la capa física", "En la capa de red", "En la capa de transporte"], "c": [0], "why": "La placa pone y saca bits del medio (física) y arma y revisa tramas con su dirección MAC (subcapa MAC de la capa de enlace). Ojo: No llega a la capa de red: no usa direcciones IP para encaminar.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "¿En qué capa del modelo OSI trabaja el puente (bridge)?", "o": ["Red", "Física", "Transporte", "Enlace de datos"], "c": [3], "why": "El bridge reenvía o filtra tramas entre segmentos según la dirección MAC, que es información de la capa de enlace. Ojo: No trabaja en la capa de red: no mira direcciones IP ni divide dominios de broadcast.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "¿Con qué direcciones trabaja el puente?", "o": ["IP", "Puertos TCP/UDP", "MAC", "Nombres de dominio (DNS)"], "c": [2], "why": "El bridge arma su tabla con las MAC de origen que ve en cada segmento y decide según la MAC destino de cada trama. Ojo: Las direcciones IP las usa el router, que trabaja una capa más arriba.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "Ethernet, Fast Ethernet y Giga Ethernet ejecutan funciones de las capas…", "o": ["Subcapa LLC y capa de red", "Capa de red y capa de transporte", "Capa física y subcapa MAC de la capa de enlace", "Solo la capa física"], "c": [2], "why": "Las normas 802.3 definen el medio y las señales (capa física) y el formato de trama y el acceso al medio (subcapa MAC). La subcapa LLC no es parte de 802.3. Ojo: Ethernet no llega a la capa de red: el direccionamiento IP y el encaminamiento son de otra capa.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Forms PDF 1 · Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "¿Con qué direcciones se comunican los hosts dentro de una misma LAN?", "o": ["Números de puerto", "Nombres de dominio", "Direcciones IP públicas", "Direcciones MAC"], "c": [3], "why": "Dentro de la misma LAN la entrega la hace la capa de enlace: la trama lleva la MAC destino y el switch la usa para reenviarla, sin pasar por un router. Ojo: Las IP públicas sirven para alcanzar equipos en Internet, no para la entrega dentro de la LAN.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "¿Cuál es el comando que permite observar la dirección MAC de la placa de red de un host?", "o": ["netstat", "ping", "tracert", "arp -a", "ipconfig /all"], "c": [4], "why": "ipconfig /all muestra la configuración completa de cada adaptador, incluida la «Dirección física», que es la MAC. Ojo: arp -a muestra la tabla ARP: las MAC de otros equipos con los que se habló, no la de la propia placa.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "¿Qué protocolos se encuentran en la capa de transporte del modelo TCP/IP?", "o": ["TPC y UDP", "Ninguna de las opciones", "TCP e IPx", "TCP e IP", "TCP y PDU"], "c": [0], "why": "Los protocolos de transporte de TCP/IP son TCP y UDP. IP e IPX son de la capa de red, y PDU es el nombre genérico de una unidad de datos, no un protocolo.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t2", "pr": false, "q": "Protocolo de ordenamiento: ¿qué protocolo se encarga de entregar los datos ordenados a la aplicación en el destino?", "o": ["IPv4", "TCP", "UDP", "Ethernet", "ARP"], "c": [1], "why": "TCP numera los segmentos y en el destino los reordena antes de entregarlos a la aplicación. IPv4 encamina cada paquete por separado y no garantiza orden; UDP tampoco ordena. La consigna te llegó incompleta («Protocolo de ordenamiento»): por eso figura como discutible.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t2", "q": "¿Qué protocolos se encuentran en la capa de transporte del modelo TCP/IP? (en la pregunta las opciones eran todas de otras capas)", "o": ["IP e ICMP", "HTTP y FTP", "Ethernet y PPP", "Ninguna de las opciones"], "c": [3], "why": "Los de transporte son TCP y UDP. Si no aparecen, la respuesta es 'Ninguna de las opciones'. Leé bien todas las opciones.", "src": "Preguntero 1er parcial (zip)", "pr": false},
{"b": "t2", "q": "¿En qué capa del modelo OSI trabaja el puente (bridge)?", "o": ["Solo física", "Red", "Transporte", "Aplicación", "Física y enlace de datos"], "c": [4], "why": "El bridge recibe bits (física) y decide por MAC (enlace). En el preguntero la respuesta fue 'física y enlace de datos'.", "src": "Preguntero 1er parcial (zip)", "pr": false},
{"b": "t3", "pr": false, "q": "Si hablamos de Internet, podemos decir que es una red… (seleccione cuatro)", "o": ["Conmutada por paquetes", "Con tasa de bits constante", "Basada en protocolos propietarios de pocas empresas", "Conmutada por circuitos", "De amplia cobertura geográfica", "Tolerante a fallas", "Basada en protocolos normalizados y públicos", "Que no posee redundancia"], "c": [0, 4, 5, 6], "why": "Internet parte los datos en paquetes que viajan por caminos redundantes: si un enlace cae, se usan otros. Cubre todo el planeta y usa protocolos abiertos, publicados en las RFC. Ojo: La tasa de bits constante es propia de la conmutación de circuitos, no de Internet.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t3", "pr": false, "q": "La ARPANET estaba montada sobre una red de:", "o": ["Conmutación de circuitos", "Retransmisión de tramas (Frame Relay)", "Conmutación de celdas", "Conmutación de paquetes"], "c": [3], "why": "ARPANET, antecesora de Internet, partía los mensajes en paquetes que viajaban sin un camino reservado. Así la red seguía funcionando aunque cayeran algunos nodos. Ojo: La conmutación de circuitos es la de la telefonía clásica: reserva un camino fijo y se corta si ese camino falla.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t3", "pr": false, "q": "Las RFC (Request For Comments) son un conjunto de documentos que sirven de referencia para la comunidad de Internet, utilizados para la implementación, estandarización y discusión de normas, estándares, tecnologías y protocolos, emitidas por el IETF.", "o": ["Verdadero", "Falso"], "c": [0], "why": "La IETF publica su documentación técnica como RFC. Ahí se definen los protocolos de Internet, como IP, TCP o HTTP.", "src": "UV 2020 (revisiones) · Teóricas 1.er parcial · Forms PDF 3 (preguntero web)"},
{"b": "t3", "pr": false, "q": "¿Quién regula las telecomunicaciones internacionales?", "o": ["IETF", "ISO", "IEEE", "ITU"], "c": [3], "why": "La ITU (Unión Internacional de Telecomunicaciones) es el organismo que coordina las telecomunicaciones entre países. Ojo: La IEEE hace normas para LAN (familia 802), no regula las telecomunicaciones entre países.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t3", "pr": false, "q": "¿Cuál es una organización voluntaria que emite estándares internacionales en cualquier ámbito?", "o": ["IETF", "IEEE", "ITU", "ISO"], "c": [3], "why": "ISO reúne a los organismos nacionales de normalización y emite estándares de todo tipo, no solo de redes; por ejemplo, el modelo OSI. Ojo: La ITU se ocupa solo de las telecomunicaciones.", "src": "Forms PDF 1 · Forms PDF 3 · Forms preguntero 1.er parcial · Lista que pasaste (23/11) (preguntero web)"},
{"b": "t3", "pr": false, "q": "Las normas de las redes LAN las definen y administran…", "o": ["IETF", "ITU", "ISO", "IEEE"], "c": [3], "why": "El comité IEEE 802 define y mantiene las normas de LAN: 802.3 Ethernet, 802.11 Wi-Fi, 802.15 Bluetooth, entre otras. Ojo: La IETF hace los protocolos de Internet (las RFC), no las normas de las LAN.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t3", "pr": false, "q": "¿Qué organismo hace trabajos de investigación a corto plazo sobre los protocolos de Internet?", "o": ["IRTF", "ITU", "IEEE", "ISO", "IETF"], "c": [4], "why": "La IETF resuelve problemas de ingeniería de corto plazo sobre los protocolos de Internet y publica las RFC. Ojo: La IRTF también estudia Internet, pero con investigación a largo plazo.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t3", "pr": false, "q": "Indique la asociación correcta entre tecnologías y números de estándar IEEE.", "o": ["Wi-Max 802.11 · Token Ring 802.5 · Bluetooth 802.15 · Wi-Fi 802.16 · Ethernet 802.3", "Wi-Max 802.16 · Token Ring 802.5 · Bluetooth 802.15 · Wi-Fi 802.11 · Ethernet 802.3", "Wi-Max 802.16 · Token Ring: no tiene estándar IEEE · Bluetooth 802.15 · Wi-Fi 802.11 · Ethernet 802.3", "Wi-Max 802.16 · Token Ring 802.15 · Bluetooth 802.5 · Wi-Fi 802.11 · Ethernet 802.3", "Wi-Max 802.16 · Token Ring 802.5 · Bluetooth 802.15 · Wi-Fi 802.3 · Ethernet 802.11"], "c": [1], "why": "Cada tecnología tiene su número dentro de la familia IEEE 802: Ethernet 802.3, Token Ring 802.5, Wi-Fi 802.11, Bluetooth 802.15 y WiMax 802.16. Ojo: Token Ring sí tiene estándar IEEE: es el 802.5.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t3", "pr": false, "q": "¿Cuál es una ventaja de la normalización?", "o": ["Las redes dejan de necesitar protocolos", "El usuario tiene más libertad y flexibilidad para elegir dónde comprar", "Los equipos solo funcionan con otros de la misma marca", "Cada fabricante puede cambiar el protocolo a su gusto sin afectar a nadie"], "c": [1], "why": "Si todos los fabricantes siguen la misma norma, sus equipos se entienden entre sí. Así el usuario puede mezclar marcas y elegir proveedor. Ojo: Atar los equipos a una sola marca es justamente lo que la normalización evita.", "src": "Forms PDF 3 (preguntero web)"},
{"b": "t3", "pr": false, "q": "¿Cuáles de las siguientes afirmaciones sobre la arquitectura de Internet son correctas? (Seleccione dos)", "o": ["Las redes Tier 3 dan conexión a usuarios residenciales y empresas", "Las redes Tier 2 le venden tránsito a las redes Tier 1", "Las redes Tier 3 tienen una infraestructura de fibra global propia", "Las redes Tier 1 pertenecen a grandes operadores con fibra en al menos dos continentes", "Los IXP unen operadores mediante acuerdos de tránsito pagos"], "c": [0, 3], "why": "Tier 1 son la columna vertebral global de Internet; Tier 2 son regionales y compran tránsito a Tier 1; Tier 3 son locales y llegan al usuario final. Ojo: Es al revés: el Tier 2 le compra tránsito al Tier 1. Y en un IXP se hace peering, no tránsito.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial · Lista que pasaste (23/11) (preguntero web)"},
{"b": "t3", "pr": false, "q": "¿Qué infraestructura permite que distintos ISP intercambien tráfico mediante peering?", "o": ["Punto de intercambio de Internet (IXP)", "Central telefónica de conmutación de circuitos", "Access point", "Red Tier 3 de acceso", "Servidor DNS raíz"], "c": [0], "why": "Un IXP es un lugar físico donde muchos ISP conectan sus routers para intercambiar tráfico directamente entre ellos, sin pagar tránsito. Ojo: Un access point se llama parecido, pero es un equipo de una WLAN, no un punto de interconexión entre ISP.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t3", "pr": false, "q": "¿Cuáles de las siguientes características corresponden a las conexiones de tránsito? (Seleccione tres)", "o": ["El proveedor le da al cliente acceso a todas sus rutas", "El intercambio de tráfico es sin costo", "El operador de menor jerarquía le paga al de mayor jerarquía", "Conectan operadores de distinta jerarquía", "Cada operador publica solo sus propias rutas"], "c": [0, 2, 3], "why": "En el tránsito, un operador le compra a otro de mayor jerarquía el acceso al resto de Internet: paga y a cambio recibe todas las rutas. Ojo: Publicar solo las rutas propias y no cobrarse es lo que define al peering.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t3", "pr": false, "q": "¿Cuáles de las siguientes características corresponden a las conexiones de peering? (Seleccione tres)", "o": ["Los operadores intercambian tráfico sin costo", "El proveedor le da al cliente acceso a todas sus rutas", "Cada operador publica solo sus propias rutas", "El operador de menor jerarquía le paga al de mayor jerarquía", "Pueden ser públicas o privadas"], "c": [0, 2, 4], "why": "En el peering dos operadores se pasan solo el tráfico de sus propios clientes, de igual a igual y sin pagarse. Puede hacerse en un IXP (público) o con un enlace directo (privado). Ojo: Pagarle al de mayor jerarquía para recibir todas sus rutas es tránsito, no peering.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t3", "pr": false, "q": "Internet es:", "o": ["Una red privada de intercambio de información académica", "Una red WAN", "Una red de redes", "Una red MAN", "Una red tolerante a fallas tanto de sus enlaces como de sus nodos", "Una red LAN", "Una red conmutada por paquete", "Una red conmutada por paquetes"], "c": [1, 2, 4, 6, 7], "why": "Internet es una red de redes de alcance mundial (WAN), conmutada por paquetes y diseñada para ser tolerante a fallas: si cae un enlace o un nodo, los paquetes toman otro camino. No es privada ni académica (eso fue ARPANET en sus orígenes) y no es LAN ni MAN, porque su cobertura es global. Las opciones «conmutada por paquete» y «por paquetes» dicen lo mismo.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t3", "pr": false, "q": "Quién fue el creador de la ARPANET?", "o": ["Ninguna", "TCP / IP", "IEEE", "ISO", "DARPA", "ITU", "ETS"], "c": [4], "why": "ARPANET (1969) la desarrolló DARPA, la Agencia de Proyectos de Investigación Avanzada de Defensa de EE. UU. TCP/IP es un conjunto de protocolos, no un creador, e IEEE, ISO e ITU son organismos de normalización.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t3", "pr": false, "q": "Cuando se necesita un estándar, se discutía y después anunciaban el o los cambios formalmente. La comunicación se llevaba a cabo por informes técnicos llamados:", "o": ["Informes de cambios", "OSI", "Informes técnicos", "Ninguna de las opciones", "RFC"], "c": [4], "why": "Los RFC (Request for Comments) son los informes técnicos con los que la comunidad de Internet propone, discute y anuncia formalmente los protocolos y estándares; hoy los publica la IETF. OSI es un modelo de referencia, no un tipo de informe.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t3", "pr": false, "q": "Los Request for Comments son", "o": ["Documentos tecnicos que describen el funcionamiento de los protocolos de internet", "Bases de datos que asocian dominios con direcciones IP", "Estandares que definen la arquitectura de un sistema operativo", "Documentos técnicos establecidos por el IEEE"], "c": [0], "why": "Un RFC es un documento técnico que describe cómo funcionan los protocolos de Internet (TCP, IP, HTTP, etc.) y lo publica la IETF, no el IEEE. Asociar dominios con IP es tarea del DNS.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t3", "pr": false, "q": "Los estándares Ethernet, Fast Ethernet, Giga Ethernet y Wi-Fi fueron definidos por:", "o": ["IETF", "IEEE", "ITU", "ISO", "ICANN"], "c": [1], "why": "El IEEE define los estándares de redes locales de la familia 802: 802.3 (Ethernet, Fast Ethernet 802.3u, Giga Ethernet 802.3ab/z) y 802.11 (Wi-Fi). Ojo: el IETF hace los estándares de Internet (RFC), como IP o TCP.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t3", "pr": false, "q": "¿Cuál de los organismos internacionales desarrolla trabajo de investigación a largo plazo relacionado con los protocolos de Internet?", "o": ["IETF", "ISO", "ITU", "IRTF", "RFC", "IEEE"], "c": [3], "why": "El IRTF (Internet Research Task Force) investiga a largo plazo; el IETF (Internet Engineering Task Force) trabaja a corto plazo, en la ingeniería de los estándares. Ojo: RFC no es un organismo, son los documentos donde el IETF publica sus estándares.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t3", "q": "Indique los números de estándares IEEE que se corresponden con las siguientes tecnologías:", "filas": ["Wi-Max", "Token Ring", "Bluetooth", "Wi-Fi", "Ethernet"], "o": ["IEEE 802.3", "IEEE 802.5", "IEEE 802.11", "IEEE 802.15", "IEEE 802.16", "No corresponde a ningún estándar IEEE"], "c": [4, 1, 3, 2, 0], "why": "802.3 Ethernet, 802.5 Token Ring, 802.11 Wi-Fi, 802.15 Bluetooth (PAN), 802.16 WiMAX. Ojo: Token Ring SÍ es IEEE (802.5).", "src": "Moodle 1er Parcial 4K4 (2020)", "pr": false},
{"b": "t3", "q": "Organización voluntaria que emite estándares en el ámbito científico, tecnológico, industrial y de sistemas de información:", "o": ["IEEE", "IETF", "ITU", "ISO", "RFC"], "c": [0], "why": "La IEEE es una organización profesional voluntaria de ingenieros; su comité 802 define las LAN.", "src": "Preguntas 4K1", "pr": false},
{"b": "t3", "q": "Un usuario residencial normalmente se conecta a Internet a través de:", "o": ["Un ISP Tier 3 (local), que compra tránsito a niveles superiores", "Directamente a un ISP Tier 1", "Un IXP, sin ISP", "La IANA"], "c": [0], "why": "Tier 3 = última milla. Compra tránsito a Tier 2/Tier 1; los Tier 1 se interconectan por peering (en IXP).", "src": "Preguntas 4K1", "pr": false},
{"b": "t4", "pr": false, "q": "¿En cuál de estos dispositivos se ejecuta CSMA/CD?", "o": ["Placas de red inalámbricas", "Puertos de switch en full dúplex", "Placas de red Ethernet", "Access point"], "c": [2], "why": "CSMA/CD es el método de acceso de Ethernet (802.3). Lo ejecuta la placa de red: escucha el cable, transmite y detecta si hubo colisión. Ojo: Las placas inalámbricas y el access point usan CSMA/CA, porque en el aire no pueden detectar colisiones.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": false, "q": "¿En cuáles de estos dispositivos se ejecuta CSMA/CA? (Seleccione dos)", "o": ["Access point", "Switch", "Placas de red Ethernet", "Placas de red inalámbricas", "Hub"], "c": [0, 3], "why": "CSMA/CA es el método de acceso de 802.11. Lo ejecutan todos los que transmiten por el aire: las placas inalámbricas y el access point. Ojo: Las placas Ethernet usan CSMA/CD sobre el cable.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": false, "q": "¿Qué trama usa una estación cuando quiere transmitir a otra utilizando CSMA/CA?", "o": ["Token", "NAK", "ACK", "RTS", "CTS"], "c": [3], "why": "Con CSMA/CA el origen pide permiso con una trama corta RTS (request to send). Si el destino está listo, contesta con CTS. Ojo: CTS es la respuesta del destino que concede el permiso, no el pedido.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": false, "q": "En la transmisión inalámbrica, RTS es…", "o": ["Una trama de datos", "Un paquete de capa de red", "Una trama de control", "Una trama de administración"], "c": [2], "why": "802.11 usa tramas de datos, de control y de administración. RTS, CTS y ACK son de control: coordinan el acceso al medio y no llevan datos del usuario. Ojo: Las de administración son otras, como los beacons y la asociación con el access point.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": false, "q": "En CSMA/CA, el mensaje RTS contiene…", "o": ["Las direcciones MAC del origen y del destino", "Las direcciones IP del origen y del destino", "Solo la dirección MAC de broadcast", "El SSID de la red", "Los datos que se van a transmitir"], "c": [0], "why": "La RTS es una trama corta de control que solo anuncia quién quiere transmitir y a quién: lleva la MAC del origen y la del destino. Ojo: Las direcciones IP viajan dentro del paquete; la RTS es de la capa de enlace.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": false, "q": "En el método de acceso de las redes inalámbricas, los dispositivos que quieren transmitir…", "o": ["Escuchan el medio; si está libre, esperan un tiempo aleatorio y envían un RTS con las MAC de origen y destino", "Transmiten la trama de datos apenas tienen algo para enviar y, si hay colisión, la repiten", "Escuchan el medio mientras transmiten la trama de datos para detectar colisiones", "Esperan a recibir el token para poder transmitir"], "c": [0], "why": "Con CSMA/CA la estación escucha el canal; si está libre, espera un tiempo aleatorio corto y anuncia su intención con un RTS. Así evita la colisión antes de mandar los datos. Ojo: Detectar colisiones mientras se transmite es CSMA/CD, de Ethernet; en el aire no se puede.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": false, "q": "¿Qué campo de la trama Ethernet permite verificar su integridad?", "o": ["Preámbulo", "Delimitador de inicio de trama (SFD)", "Dirección MAC de origen", "Tipo", "Secuencia de verificación de trama (FCS)"], "c": [4], "why": "El emisor calcula un CRC sobre la trama y lo pone en el FCS, al final. El receptor lo recalcula: si no coincide, la trama llegó dañada. Ojo: El preámbulo solo sincroniza al receptor; no controla errores.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": false, "q": "Una placa de red calcula el CRC de una trama recibida y no coincide con el que trae la trama. ¿Qué hace?", "o": ["Corrige los bits erróneos y la procesa", "Descarta la trama", "Le pide al emisor que la retransmita", "Le avisa al emisor con un mensaje de error"], "c": [1], "why": "Ethernet detecta errores pero no los corrige ni pide reenvío: si el CRC no coincide, la placa descarta la trama. Recuperar los datos queda en manos de capas superiores, como TCP. Ojo: Pedir retransmisión no es tarea de la placa Ethernet; lo hace, si corresponde, TCP en el host.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial · Lista que pasaste (23/11) (preguntero web)"},
{"b": "t4", "pr": false, "q": "Una placa de red recibe una trama cuya dirección MAC de origen es FF:FF:FF:FF:FF:FF. ¿Qué hace?", "o": ["La descarta", "La reenvía a todos los equipos de la LAN", "La procesa, porque es un broadcast", "Responde con su propia dirección MAC"], "c": [0], "why": "La MAC de origen identifica a quien envía y siempre es unicast. La dirección de difusión (los 48 bits en 1) solo puede ir en el campo destino, así que la trama es inválida. Ojo: Procesarla como broadcast correspondería si FF:FF:FF:FF:FF:FF estuviera en el destino, no en el origen.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": false, "q": "La dirección 01:00:5E:00:04:C9 aparece en el campo destino de una trama. ¿Quién la procesará?", "o": ["Solo un grupo de máquinas de la LAN", "Una única máquina de la LAN", "Todas las máquinas de la LAN", "Ninguna, porque es una dirección inválida"], "c": [0], "why": "Las MAC que empiezan con 01:00:5E son multicast: el último bit del primer byte en 1 indica una dirección de grupo. Solo las placas que pertenecen a ese grupo la procesan. Ojo: Todas la procesarían solo si el destino fuera FF:FF:FF:FF:FF:FF (broadcast).", "src": "Forms PDF 1 · Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": false, "q": "Para que todos los dispositivos de la LAN procesen la trama, la dirección MAC de destino será…", "o": ["FF-FF-FF-FF-FF-FF", "255.255.255.255", "00-00-00-00-00-00", "01-00-5E-00-00-01", "La MAC de la puerta de enlace"], "c": [0], "why": "La MAC de difusión tiene los 48 bits en 1 (FF-FF-FF-FF-FF-FF): todas las placas del segmento aceptan esa trama. Ojo: 255.255.255.255 también es broadcast, pero es una dirección IP (capa de red), no una MAC.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": true, "q": "Una trama Ethernet mide 1458 bytes. ¿Cuántos bytes ocupa su carga útil (el paquete IPv4)?", "o": ["1432 bytes", "1458 bytes", "1440 bytes", "1444 bytes", "1454 bytes"], "c": [2], "why": "La trama Ethernet suma 18 bytes de control: MAC destino (6) + MAC origen (6) + tipo (2) + FCS (4). La carga útil es 1458 − 18 = 1440 bytes. Ojo: El preámbulo no cuenta en el tamaño de la trama; por eso el mínimo de 64 bytes deja 46 de datos (64 − 18).", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": true, "q": "Una trama inalámbrica mide 1554 bytes. ¿Cuántos bytes ocupa su carga útil (el paquete IPv4 o IPv6)?", "o": ["1500 bytes", "1520 bytes", "1536 bytes", "1554 bytes"], "c": [1], "why": "La trama 802.11 tiene más campos que Ethernet (hasta cuatro direcciones, control, duración y secuencia): entre encabezado y FCS suma 34 bytes. 1554 − 34 = 1520 bytes. Ojo: Restar 18 bytes (1536) es la cuenta de una trama Ethernet, no de una inalámbrica.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": false, "q": "Se envía un archivo de 5 KB por Fast Ethernet, aprovechando al máximo la MTU. ¿Cuántas tramas hacen falta?", "o": ["4", "5", "1", "3"], "c": [0], "why": "La MTU de Ethernet es 1500 bytes de carga por trama. 5 KB = 5120 bytes; 5120 / 1500 = 3,4, así que hacen falta 4 tramas: 3 llenas y una con el resto. Ojo: Con 3 tramas solo entran 4500 bytes: los 620 que sobran necesitan una cuarta.", "src": "Forms PDF 3 (preguntero web)"},
{"b": "t4", "pr": false, "q": "¿Cuál es la máxima tasa de bits a la que funcionará una LAN Ethernet si el switch tiene 24 puertos de 1 Gb/s, dos puertos de fibra de 10 Gb/s, el cableado está certificado para categoría 6 y las placas de red de las PC son Fast Ethernet?", "o": ["24 Gb/s", "22,4 Gb/s", "1 Gb/s", "2,4 Gb/s", "100 Mb/s"], "c": [4], "why": "La velocidad efectiva la marca el eslabón más lento. Las placas Fast Ethernet de las PC van a 100 Mb/s, aunque el switch y el cable soporten más. Ojo: Sumar puertos no da la tasa de la LAN: cada enlace va a la velocidad que negocian sus dos extremos.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": false, "q": "En una PC se cambia la placa de red Fast Ethernet por una Giga Ethernet. ¿Qué sucede? (Seleccione dos)", "o": ["La PC será 100 veces más rápida", "La placa podrá trabajar a 1000 Mbps", "La PC conservará la misma dirección MAC", "La PC tendrá otra dirección MAC", "Habrá que reemplazar el cable UTP por fibra óptica"], "c": [1, 3], "why": "Giga Ethernet trabaja a 1000 Mbps, 10 veces Fast Ethernet. La MAC viene grabada en cada placa, así que al cambiar la placa cambia la MAC de la PC. Ojo: No es 100 veces más rápida: de 100 a 1000 Mbps es 10 veces.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial · Lista que pasaste (23/11) (preguntero web)"},
{"b": "t4", "pr": false, "q": "Hay que conectar tres edificios de un campus: A está a 300 m de B, C está a 250 m de A y C está a 350 m de B. ¿Qué tecnología se podría implementar?", "o": ["1000BASE-T", "100BASE-TX", "1000BASE-CX", "10BASE-T", "1000BASE-SX"], "c": [4], "why": "El tramo más largo es de 350 m. 1000BASE-SX usa fibra multimodo y llega a 550 m; las variantes de cobre llegan a 100 m o menos. Ojo: 1000BASE-T es Gigabit, pero por UTP: su tramo máximo es de 100 m.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": true, "q": "Microsoft Azure es un servicio de computación en la nube creado por Microsoft para construir, probar, desplegar y administrar aplicaciones y servicios mediante el uso de sus centros de datos. Respecto de la siguiente es una captura de paquetes realizada mientras un host de una LAN estaba navegando por Internet", "o": ["EC:43:F6:B5:B4:F4", "No se puede deducir de la captura", "LiteonTe"], "filas": ["Dirección MAC del host que envía el mensaje", "Dirección MAC de la puerta de enlace de la LAN", "Dirección MAC de Microsoft Azure"], "c": [2, 0, 1], "img": "fig_13", "why": "La trama sale del host (MAC de origen LiteonTe_f3:db:26) hacia la puerta de enlace (MAC de destino ec:43:f6:b5:b4:f4, el router ZyXEL), aunque la IP de destino sea la de Azure. Las MAC solo tienen sentido dentro de la LAN: la del servidor de Azure, que está en otra red, nunca aparece en la trama.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t4", "pr": false, "q": "¿Qué funciones cumple la placa de red (NIC) en el DESTINO cuando recibe una trama? (elegí tres)", "o": ["Calcula el CRC y lo compara con el FCS de la trama", "Compara la MAC de destino con la propia (o con broadcast/multicast)", "Desencapsula la trama y entrega el paquete a la capa de red", "Agrega el encabezado de la trama y calcula el FCS", "Le asigna una dirección IP al paquete recibido"], "c": [0, 1, 2], "why": "En el destino la placa verifica la integridad (CRC contra FCS: si no coincide, descarta), mira si la trama es para ella (MAC propia, broadcast o un grupo) y, si corresponde, saca el encabezado y entrega el paquete a la capa de red. Ojo: armar el encabezado y calcular el FCS es lo que hace la placa en el ORIGEN.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t4", "pr": false, "q": "¿Cuál es el método de acceso al medio más adecuado según la topología y la tecnología?", "o": ["CSMA/CD", "CSMA/CA", "Paso de testigo (token)"], "filas": ["Red Ethernet cableada con medio compartido (hub)", "Red inalámbrica IEEE 802.11", "Red Token Ring (IEEE 802.5)"], "c": [0, 1, 2], "why": "En el cable compartido una estación puede escuchar mientras transmite, así que detecta la colisión (CSMA/CD). En el aire no puede detectarla, así que trata de evitarla (CSMA/CA, con espera aleatoria y RTS/CTS). Token Ring no compite: transmite solo quien tiene el testigo.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t4", "pr": false, "q": "Afirmaciones sobre una trama procesada por una placa de red Fast Ethernet: ¿cuáles son correctas? (elegí dos)", "o": ["Si la MAC de destino no es la suya, ni broadcast, ni de un grupo al que pertenece, la descarta", "Si el FCS no coincide con el CRC calculado, descarta la trama", "Si hay un error, le pide al origen que retransmita la trama", "Trabaja a 1000 Mbps", "Lee la dirección IP del paquete para decidir si procesa la trama"], "c": [0, 1], "why": "La placa decide con datos de la trama (capa de enlace): la MAC de destino y el FCS. No mira la IP (eso es de la capa de red) y Ethernet no pide retransmisiones: detecta errores y descarta. Fast Ethernet trabaja a 100 Mbps. La consigna te llegó sin opciones: está armada con lo que toman y figura como discutible.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t4", "pr": true, "q": "Microsoft Azure es un servicio de computación en la nube creado por Microsoft para construir, probar, desplegar y administrar aplicaciones y servicios mediante el uso de sus centros de datos. La siguiente es una captura de paquetes realizada mientras un host estaba navegando por Internet: En ella se puede observar que la dirección MAC del router de la LAN es: ec:43:f6:b5:b4:f4", "o": ["Verdadero", "Falso"], "c": [0], "img": "azure_captura", "why": "El destino (52.109.108.44) está fuera de la LAN, así que el host arma la trama hacia su puerta de enlace: la MAC de destino de la trama es la del router de la LAN (ZyxelCom, ec:43:f6:b5:b4:f4), no la del servidor.", "src": "UV 2020 (revisiones) · Forms PDF 2, pág. 9 (preguntero web)"},
{"b": "t4", "pr": true, "q": "Microsoft Azure es un servicio de computación en la nube creado por Microsoft para construir, probar, desplegar y administrar aplicaciones y servicios mediante el uso de sus centros de datos. La siguiente es una captura de paquetes realizada mientras un host estaba navegando por Internet: En ella se puede observar que la dirección MAC del servidor de Microsoft es: ec:43:f6:b5:b4:f4", "o": ["Verdadero", "Falso"], "c": [1], "img": "azure_captura", "why": "Las direcciones MAC solo sirven dentro de la propia LAN. Para llegar a un servidor de otra red, la trama lleva como MAC de destino la del router de la LAN (ec:43:f6:b5:b4:f4); la MAC del servidor de Microsoft nunca aparece en la captura.", "src": "UV 2020 (revisiones) · Forms PDF 2, pág. 22 (preguntero web)"},
{"b": "t4", "q": "En el método de acceso CSMA/CA, el mensaje RTS contiene:", "o": ["Números de puerto origen y destino", "Relación IP – MAC del dispositivo destino", "Direcciones MAC del dispositivo origen y destino (y el tiempo de transmisión)", "Direcciones IP del dispositivo origen y destino"], "c": [2], "why": "RTS es una trama de capa 2: lleva MAC origen, MAC destino y la duración (tiempo) que va a ocupar el canal, para que las demás estaciones esperen (NAV).", "src": "Revisión en clase del 1er parcial", "pr": false},
{"b": "t4", "q": "Una PC tiene que enviar un archivo de 5 Kbytes a través de FastEthernet. Si desea maximizar el uso de la MTU, ello implica que enviará:", "o": ["5 tramas", "2 tramas", "4 tramas", "3 tramas", "1 trama"], "c": [2], "why": "La MTU de Ethernet es 1500 bytes. 5 KB = 5120 bytes → 5120 / 1500 = 3,4 → hacen falta 4 tramas (3 llenas + 1 parcial).", "src": "Revisión en clase del 1er parcial", "pr": true},
{"b": "t4", "q": "Captura de Wireshark de un host navegando por Internet (servidor de Microsoft Azure). La MAC destino de las tramas salientes era ec:43:f6:b5:b4:f4. ¿De quién es esa MAC?", "o": ["Del servidor de Microsoft Azure", "Del router (puerta de enlace) de la LAN", "Del switch de la LAN", "Del host que envía el mensaje"], "c": [1], "why": "Para ir a otra red la trama se dirige a la MAC del GATEWAY. La MAC del servidor remoto nunca se ve en la LAN (no se puede deducir de la captura). El switch no tiene MAC destino en las tramas.", "src": "Moodle 1er Parcial 4K4 (2020)", "pr": true},
{"b": "t5", "pr": true, "q": "¿Qué dispositivo divide dominios de colisión?", "o": ["Repetidor", "Switch", "Hub", "Patchera"], "c": [1], "why": "Cada puerto del switch es un dominio de colisión aparte: las tramas de un puerto no chocan con las de otro. Ojo: El hub y el repetidor reenvían los bits por todos sus puertos, así que extienden el dominio de colisión.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": true, "q": "Un switch de 24 puertos tiene un hub en el puerto 1, otro hub en el puerto 2, un router en el puerto 3 y computadoras en el resto. ¿Cuántos dominios de colisión existen?", "o": ["21", "24", "1", "3", "26"], "c": [1], "why": "Cada puerto del switch es un dominio de colisión, tenga colgada una PC, un hub con varias PC o un router. 24 puertos ocupados dan 24 dominios. Ojo: Las PC que cuelgan de un hub no suman dominios: comparten el del puerto donde está el hub.", "src": "Teóricas 1.er parcial · Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": true, "q": "Un switch de 24 puertos tiene un hub en el puerto 1, otro hub en el puerto 2, un router en el puerto 3 y computadoras en el resto. ¿Cuántos dominios de broadcast hay del lado del switch?", "o": ["3", "1", "24", "2"], "c": [1], "why": "Ni el switch ni los hubs dividen el broadcast: todo lo que cuelga del switch forma un solo dominio. Solo el router separa dominios, y sus otras interfaces no se muestran. Ojo: 24 es la cuenta de dominios de colisión, no de broadcast.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Forms PDF 1 (preguntero web)"},
{"b": "t5", "pr": false, "q": "Determine a partir de la topología, cuáles de las afirmaciones son correctas (seleccione dos):", "o": ["Existen dos dominios de broadcast", "Existen 3 dominios de broadcast", "Existe un dominio de broadcast", "Existen 7 dominios de colisión", "Existen 6 dominios de colisión", "Existen 5 dominios de colisión", "Existen 4 dominios de colisión"], "c": [0, 4], "img": "p66", "why": "Cada interfaz del router es un dominio de broadcast: 2. En colisión, todo el hub es 1 dominio y cada puerto usado del switch es otro (4 PC + el enlace al router = 5): 1 + 5 = 6. Ojo: Las PC del hub no son dominios separados: comparten uno solo. Con la figura real: Figura real: router con un hub (PC4, PC5, PC6) en una interfaz y un switch (PC0–PC3) en la otra. La respuesta no cambia: 2 de broadcast y 6 de colisión.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": false, "q": "Determine a partir de la topología, cuáles de las afirmaciones son correctas (seleccione dos):", "o": ["Existen 5 dominios de colisión", "Existen dos dominios de broadcast", "Existen 7 dominios de colisión", "Existe un dominio de broadcast", "Existen 4 dominios de colisión", "Existen 3 dominios de broadcast", "Existen 6 dominios de colisión"], "c": [1, 2], "img": "p67", "why": "Cada interfaz del router es un dominio de broadcast: 2. En colisión, el hub entero es 1 y el switch aporta un dominio por puerto usado (5 PC + el enlace al router = 6): 1 + 6 = 7. Ojo: Contar cada PC del hub por separado (10) es el error típico: el hub no divide colisiones. Con la figura real: Figura real (Forms PDF 1, pág. 12): hub con PC8, PC4, PC5 y PC6 (4 PC) y switch con PC0, PC1, PC2, PC3 y PC7 (5 PC). La respuesta no cambia: 2 de broadcast y 7 de colisión. La opción «10 dominios de colisión» del texto actual no está en el original.", "src": "Forms PDF 1 (preguntero web)"},
{"b": "t5", "pr": true, "q": "Si en una LAN se tienen 3 Switch como los de la figura, interconectados de la siguiente forma: ¿Hasta cuántos dominios de broadcast podría haber?", "o": ["2", "3", "1", "Uno por cada puerto de los switches"], "c": [2], "img": "p68", "why": "Los switches dividen dominios de colisión, pero reenvían el broadcast por todos sus puertos. Sin un router que los separe, toda la LAN es un solo dominio de broadcast. Ojo: Uno por puerto es la regla de los dominios de colisión, no de broadcast. Con la figura real: En la UV era de respuesta numérica y la correcta oficial es 1 (revisión UV 2020, Forms PDF 2, pág. 58): se puede quitar «dudosa». La figura es un switch AirLive SNMP-GSH2804L (24 RJ45 + 4 SFP) y 3 switches en cadena. La misma figura se usaba para la variante de colisión (82), armada en «nuevas».", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t5", "pr": false, "q": "Un administrador de red necesita mucha velocidad en su LAN. ¿Qué técnica de conmutación debe configurar en el switch?", "o": ["Libre de fragmentos (fragment free)", "Conmutación de circuitos", "Cut-through", "Almacenamiento y reenvío (store and forward)"], "c": [2], "why": "Cut-through reenvía la trama apenas lee la MAC de destino, que viene al principio. No espera el resto de la trama, así que es la técnica con menos demora. Ojo: Libre de fragmentos también es un método de corte, pero espera a leer 64 bytes: es más lenta que cut-through.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial · Lista que pasaste (23/11) (preguntero web)"},
{"b": "t5", "pr": false, "q": "Un administrador de red quiere garantizar que el switch conmute solo tramas correctas. ¿Qué técnica debe configurar?", "o": ["Spanning Tree (STP)", "Cut-through", "Libre de fragmentos (fragment free)", "Almacenamiento y reenvío (store and forward)"], "c": [3], "why": "Almacenamiento y reenvío guarda la trama completa y controla errores (el FCS) antes de reenviarla. Si la trama llegó dañada, la descarta. Ojo: Libre de fragmentos solo mira los primeros 64 bytes: filtra fragmentos de colisión, pero no controla el resto de la trama.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": true, "q": "Respecto de las técnicas de reenvío de tramas de los switches, ¿qué emparejamiento es correcto? (1) Lee los primeros 64 bytes de la trama y luego reenvía. (2) Es el método más lento: almacena toda la trama y controla que no tenga errores. (3) Transfiere la trama al puerto destino apenas lee la MAC de destino.", "o": ["1 → Libre de fragmentos; 2 → Almacenamiento y reenvío; 3 → Cut-through", "1 → Almacenamiento y reenvío; 2 → Libre de fragmentos; 3 → Cut-through", "1 → Libre de fragmentos; 2 → Cut-through; 3 → Almacenamiento y reenvío", "1 → Cut-through; 2 → Almacenamiento y reenvío; 3 → Libre de fragmentos"], "c": [0], "why": "Las tres se distinguen por cuánto leen antes de reenviar. Cut-through, solo la MAC de destino; libre de fragmentos, 64 bytes (el tamaño mínimo de trama); almacenamiento y reenvío, la trama entera, por eso es la más lenta. Ojo: Cut-through y libre de fragmentos son los dos métodos de corte y se confunden: el que espera 64 bytes es libre de fragmentos.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": false, "q": "¿Qué información se almacena en la tabla CAM de un switch?", "o": ["VLAN y máscaras de subred", "Redes de destino y próximo salto", "Puertos y direcciones IP", "Direcciones IP y direcciones MAC", "Puertos y direcciones MAC"], "c": [4], "why": "El switch trabaja en capa 2: aprende la MAC de origen de cada trama y anota por qué puerto entró. Con esa tabla decide por qué puerto sacar cada trama. Ojo: IP con MAC es la tabla ARP (de la PC o del router), no la CAM del switch.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": true, "q": "Un host que está conectado a la interfaz FastEthernet 0/5 de un switch recibe la trama de la figura: ¿Qué dirección agregará en su tabla CAM correspondiente a dicho puerto 0/5?", "o": ["24:f5:aa:70:7e:1f", "FF:FF:FF:FF:FF:FF", "192.168.1.10", "Ninguna: la tabla CAM solo guarda direcciones de destino", "00:1b:44:11:3a:b7"], "c": [0], "img": "p75", "why": "El switch aprende mirando la MAC de origen: si la trama entró por Fa0/5, el que la mandó está detrás de ese puerto. La MAC de destino la usa para decidir por dónde sacarla, no para aprender. Ojo: La MAC de destino es la que el switch busca en la tabla, pero no la agrega: no sabe en qué puerto está ese equipo. Con la figura real: Respuesta abierta en la UV; correcta oficial: 24:f5:aa:70:7e:1f (la MAC de origen de la trama). En la captura real la IP de origen es 192.168.1.9 (el texto actual dice 192.168.1.10). La respuesta no cambia.", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t5", "pr": false, "q": "A partir de la siguiente topología y tabla de direcciones MAC del switch, indique por cuáles puertos se transmitirá la trama si la máquina E le envía datos a la máquina B:", "o": ["Puertos 1, 3, 5 y 8", "Puerto 3", "Puertos 1, 3 y 8", "Puertos 1, 2, 3, 4, 6, 7 y 8"], "c": [2], "img": "p76", "why": "MAC-B no está en la tabla, así que el switch inunda: manda la trama por todos sus puertos activos menos por el que entró (el 5). Por eso sale por 1, 3 y 8. Ojo: «1, 3, 5 y 8» incluye el puerto de entrada: el switch nunca devuelve la trama por donde llegó. Con la figura real: Opciones de la revisión UV 2020 (Forms PDF 3, pág. 60). La respuesta no cambia: MAC-B no está en la tabla, así que el switch inunda por los puertos con equipos menos el de entrada (5). Los puertos 2, 4, 6 y 7 no tienen nada conectado.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": false, "q": "Una empresa tiene un switch con 20 computadoras conectadas. El administrador saca el cable del puerto 4 y lo coloca en el puerto 18. Enseguida el empleado se queja de que no tiene conectividad. ¿Cuál puede ser la causa?", "o": ["El puerto 18 es otro dominio de colisión y el switch no reenvía tramas entre dominios de colisión distintos", "La PC necesita otra dirección MAC para usar un puerto nuevo", "La tabla CAM guarda la IP de la PC asociada para siempre al puerto 4", "El switch tiene implementadas VLAN basadas en el puerto"], "c": [3], "why": "En las VLAN estáticas la pertenencia la define el puerto. Si el puerto 18 está en otra VLAN, la PC queda en otra red lógica (otra subred) y pierde conectividad con la suya. Ojo: Cada puerto sí es un dominio de colisión distinto, pero el switch reenvía entre ellos sin problema: para eso está.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": false, "q": "¿Cuál es el propósito principal del Protocolo de Árbol de Expansión (IEEE 802.1D)?", "o": ["Interconectar VLAN", "Elegir el mejor camino hacia el servidor de red", "Garantizar que no haya broadcast en una LAN", "Garantizar que no se creen loops cuando en una LAN se tengan trayectorias redundantes", "Elegir la ruta más rápida hacia la puerta de enlace de una LAN"], "c": [3], "why": "Con enlaces redundantes, las tramas de difusión darían vueltas sin fin. STP bloquea algunos puertos y convierte la malla física en un árbol lógico sin bucles; si un enlace cae, reabre un puerto bloqueado. Ojo: STP no elimina el broadcast: evita que se repita en bucle.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": false, "q": "¿Cómo se determina el switch raíz del árbol al usar STP (IEEE 802.1D)?", "o": ["Por la dirección IP más baja", "Por el ID de switch más alto", "Por el switch que tiene más puertos", "Por el ID de switch más bajo (primero la prioridad y, si empata, la MAC más baja)", "Por el switch que se encendió primero"], "c": [3], "why": "Cada switch anuncia su ID en las BPDU. El ID se arma con la prioridad y la MAC, y gana el más bajo: primero se compara la prioridad y, si empatan, la MAC. Ojo: La IP no participa: STP es de capa 2 y solo usa el ID (prioridad + MAC).", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": false, "q": "En STP, todos los puertos del switch raíz son:", "o": ["Puertos bloqueados", "Puertos desactivados", "Puertos designados", "Puertos raíz"], "c": [2], "why": "El puerto raíz es el que cada switch usa para llegar al raíz con el menor costo; el raíz no lo necesita porque él es el destino. Por eso todos sus puertos quedan designados y reenvían. Ojo: «Puertos raíz» suena lógico por el nombre, pero los puertos raíz están en los otros switches, no en el raíz.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": false, "q": "Sobre los estados de un puerto con STP, ¿qué afirmación es correcta?", "o": ["Escucha: no reenvía datos, pero envía y recibe BPDU", "Bloqueo: envía y recibe BPDU y aprende direcciones MAC", "Aprendizaje: reenvía datos, pero todavía no aprende direcciones MAC", "Envío: solo recibe BPDU y descarta las tramas de datos", "Desactivado: solo recibe BPDU para escuchar a los switches vecinos"], "c": [0], "why": "En escucha el puerto descarta los datos y no actualiza la tabla, pero ya intercambia BPDU para decidir su rol. Recién en aprendizaje carga la tabla MAC, y en envío además reenvía datos. Ojo: El que solo recibe BPDU es el bloqueo; el desactivado no procesa BPDU.", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t5", "pr": false, "q": "¿En cuáles de estos estados de STP el puerto envía y recibe BPDU? (elegí tres)", "o": ["Escucha", "Desactivado", "Envío", "Bloqueo", "Aprendizaje"], "c": [0, 2, 4], "why": "Escucha, aprendizaje y envío intercambian BPDU en los dos sentidos. Bloqueo solo las recibe (para seguir escuchando a los vecinos) y desactivado no las procesa. Ojo: Bloqueo es tentadora porque «oye» BPDU, pero solo las recibe: no las envía.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": false, "q": "Completá: «Se dice que un Access Point es un tipo de ___ porque interconecta redes cableadas que funcionan con el protocolo ___ con dispositivos inalámbricos que ejecutan ___».", "o": ["Switch; IEEE 802.11; IEEE 802.3", "Bridge; IEEE 802.5; IEEE 802.15", "Multiplexor; RS-232-C; IEEE 802.11", "Bridge; IEEE 802.3; IEEE 802.11", "Router; IEEE 802.3; IEEE 802.11"], "c": [3], "why": "El AP une dos redes en capa 2, como un puente: de un lado Ethernet cableada (802.3) y del otro Wi-Fi (802.11). No enruta: pasa tramas entre las dos tecnologías. Ojo: Router no va: un AP puro no trabaja con IP, interconecta en la capa de enlace.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": false, "q": "Modos de funcionamiento de un Access Point doméstico. ¿Qué emparejamiento es correcto? (1) Se conecta por cable UTP al módem y permite extender la cobertura. (2) Se conecta de manera inalámbrica a la red y permite extender su cobertura. (3) Puede otorgar direcciones IP y ser puerta de enlace de una red.", "o": ["1 → Router; 2 → Repetidor; 3 → Access Point/Bridge", "1 → Access Point/Bridge; 2 → Repetidor; 3 → Router", "1 → Access Point/Bridge; 2 → Módem; 3 → Repetidor", "1 → Repetidor; 2 → Access Point/Bridge; 3 → Router"], "c": [1], "why": "Como AP/bridge cuelga del módem por cable y agrega Wi-Fi. Como repetidor toma la señal inalámbrica y la retransmite para llegar más lejos. Como router, además, reparte IP y hace de puerta de enlace. Ojo: Repetidor y AP se confunden porque los dos extienden la cobertura; la diferencia es que el repetidor se engancha por Wi-Fi, no por cable.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": true, "q": "El switch de la imagen (HP A5800-24G) admite 24 conectores RJ45 y 4 conectores de fibra óptica (v o f)", "o": ["Falso", "Verdadero"], "c": [1], "img": "fig_16", "why": "En la foto se ven 24 bocas RJ45 a la izquierda y, al centro, 4 ranuras SFP, que son para módulos de fibra óptica; el puerto suelto de la derecha es el de consola. Por eso la afirmación es verdadera.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": true, "q": "Identifique las siguientes tecnologías / estándares asociados a cada placa de red", "o": ["B1", "B2", "B3", "B4", "B5", "B6"], "filas": ["IEEE 802.15", "p / Fibra óptica", "IEE 802.3", "IEE 802.11"], "c": [0, 2, [3, 4], [1, 5]], "img": "fig_08", "why": "B1 es un adaptador USB Bluetooth (IEEE 802.15, red PAN). B3 es la placa con conector de fibra óptica. La placa con boca RJ45 (marcada B4 y B5) es Ethernet cableada, IEEE 802.3. B2 (placa con antena) y B6 (adaptador USB inalámbrico) son Wi-Fi, IEEE 802.11.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": false, "q": "Una LAN implementada con Switch", "o": ["Ofrece un ancho de banda dedicado a cada uno de los host conectados", "Por difusión", "Símplex", "Es más rápida de instalar que una red tipo wi-fi", "Conmutada", "Utiliza el protocolo CSMA / CA", "Dúplex", "El ancho de banda total se divide en partes iguales entre los dispositivos conectados", "Utiliza cables UTP como medios conductores"], "c": [0, 4, 6, 8], "why": "En una LAN con switch cada puerto es su propio dominio de colisión: la red es conmutada, cada host tiene el ancho de banda del puerto para él solo y los puertos trabajan en full dúplex, normalmente con cable UTP. Dividir el ancho de banda entre todos y usar CSMA/CA son rasgos de una WLAN, y la red cableada no se instala más rápido que una Wi-Fi.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": true, "q": "De acuerdo al protocolo IEEE 802.1D; ¿cuál de los siguientes switch se convertirá en el Raiz de la siguiente topología?", "o": ["CAT1", "CAT3", "CAT4", "CAT2"], "c": [0], "img": "fig_01", "why": "El switch raíz es el de menor ID de puente, es decir, prioridad + MAC. Como los cuatro tienen la misma prioridad (32778), desempata la MAC más baja: 0017.94ba.bc80, la de CAT1. Ni la IP ni el modelo del switch cuentan.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": true, "q": "A partir de la siguiente topología, determine qué switch se elegirá como Switch raíz, cuando se ejecute el protocolo de árbol de expansión (STP):", "o": ["Switch0 y switch3", "Switch1", "Switch0", "Switch3", "Switch2"], "c": [4], "img": "fig_17", "why": "El switch raíz es el de menor ID: primero se compara la prioridad y, solo si empata, la MAC. Switch2 tiene prioridad 12536, la más baja de los cuatro, así que gana sin mirar las MAC; Switch0 y Switch3 empatan en 32768 pero pierden contra Switch2.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": true, "q": "A partir de la topología planteada, indique cuáles de las siguientes afirmaciones son correctas con respecto a los tipos de puertos", "o": ["Los puertos F0/8, F0/9 y F0/10 son puertos designados", "Los puertos F0/8, F0/9 y F0/10 son puertos raíz", "Los puertos F0/2 y F0/7, son puertos designados", "Los puertos F0/3, F0/4 y F0/5 son puertos designados", "Los puertos F0/2, F0/4 y F0/7 son puertos raíz"], "c": [0, 4], "img": "fig_10", "why": "Switch2 es la raíz (prioridad 12536, la más baja) y todos los puertos de la raíz son designados: F0/8, F0/9 y F0/10. Cada uno de los otros switches elige como puerto raíz el de menor costo hacia la raíz, que es su enlace directo: F0/2 en Switch0, F0/4 en Switch1 y F0/7 en Switch3; por eso F0/2, F0/4 y F0/7 no pueden ser designados.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": true, "q": "Luego de la convergencia del protocolo Spanning Tree, indique cuáles de los siguientes son estados en los que pueden estar los puertos troncales:", "o": ["B1", "B2", "B3", "B4", "B5"], "filas": ["Aprendiendo", "Desabilitado", "Escuchando", "Renviando", "Bloqueado"], "c": [0, 2, 1, 3, 4], "img": "fig_14", "why": "Aprendiendo (B1): manda y recibe BPDU y aprende MAC, pero todavía no reenvía datos. Escuchando (B2): solo BPDU, sin datos ni MAC. Desactivado (B3): bajado por el administrador, no participa. Reenviando (B4): datos, MAC y BPDU. Bloqueado (B5): solo recibe BPDU, y así evita los bucles.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t5", "pr": false, "q": "¿Qué dispositivos extienden el dominio de broadcast? (elegí tres)", "o": ["Hub", "Switch", "Router", "Bridge (puente)", "Gateway de capa 3"], "c": [0, 1, 3], "why": "Un broadcast llega a todos los equipos del mismo dominio: hub, switch y bridge lo dejan pasar por todos sus puertos, así que lo extienden. El router (y cualquier equipo de capa 3) no reenvía broadcasts: cada interfaz es un dominio de broadcast distinto. Ojo: switch y bridge dividen el dominio de colisión, pero extienden el de broadcast.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t5", "pr": true, "q": "Si en una LAN se tienen 3 Switch como los de la figura, interconectados de la siguiente forma: ¿Hasta cuántos dominios de colisión podría haber?", "o": ["72", "82", "84", "3", "1"], "c": [1], "img": "p68", "why": "Cada puerto de switch es un dominio de colisión, y el switch de la foto tiene 28 puertos (24 RJ45 + 4 de fibra): 3 × 28 = 84. Cada enlace entre dos switches ocupa un puerto de cada lado pero es un solo dominio, así que los 2 enlaces restan 2: 84 − 2 = 82.", "src": "UV 2020 (revisiones) · Forms PDF 2, pág. 28 (preguntero web)"},
{"b": "t5", "pr": true, "q": "A partir de la siguiente topología determine cuántos dominios de colisión existen:", "o": ["1", "14", "9", "11", "3"], "c": [1], "img": "p70", "why": "Cada puerto de switch en uso es un dominio de colisión. El switch central aporta 5 (PC0, PC1 y los 3 enlaces a los otros switches) y cada uno de los otros 3 switches suma sus 3 PC (9); el enlace al central ya se contó. 5 + 9 = 14.", "src": "Forms PDF 3 (pág. 5) · UV 2020 (preguntero web)"},
{"b": "t5", "q": "Respecto de las técnicas de reenvío de tramas de los switch, uní:", "filas": ["Lee los primeros 64 bytes de la trama y luego reenvía", "Es el método más lento: almacena toda la trama y controla que no tenga errores", "Transfiere la trama apenas lee la MAC destino"], "o": ["Cut-through", "Store and forward", "Fragment free"], "c": [2, 1, 0], "why": "Fragment free = 64 bytes (descarta fragmentos de colisión). Store and forward = trama completa + CRC (el más lento y seguro). Cut-through = solo MAC destino (el más rápido).", "src": "Moodle 1er Parcial 4K4 (2020)", "pr": false},
{"b": "t5", "q": "Estados de los puertos en STP. Uní cada descripción con su estado:", "filas": ["No envía ni recibe datos, pero recibe y envía BPDU para participar del proceso STP", "Envía y recibe BPDU y además aprende direcciones MAC, antes de reenviar tráfico", "Puerto administrativamente abajo; no participa en STP", "Envía y recibe datos, aprende MAC y procesa BPDU: es funcional a la topología", "No genera loops, no transmite datos ni aprende MAC; solo recibe BPDU"], "o": ["Bloqueado", "Escuchando", "Aprendiendo", "Reenviando", "Deshabilitado"], "c": [1, 2, 4, 3, 0], "why": "Orden: Bloqueado (solo recibe BPDU) → Escuchando (envía y recibe BPDU) → Aprendiendo (además aprende MAC) → Reenviando (todo). Deshabilitado = apagado por el admin.", "src": "Moodle 1er Parcial 4K4 (2020)", "pr": false},
{"b": "t6", "pr": false, "q": "Para dar acceso a las 3 oficinas de cada piso de un edificio de cuatro pisos, un administrador instala 4 AP. ¿Cuántos ESS tiene esa arquitectura?", "o": ["3", "12", "4", "1"], "c": [3], "why": "Cada AP forma un BSS, así que hay 4 BSS. Unidos por el sistema de distribución forman un único ESS: una sola red extendida. Ojo: 4 es la cantidad de BSS (uno por AP), no de ESS.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t6", "pr": false, "q": "Un empleado del primer piso, con una notebook conectada a un AP, le envía un mail a su supervisor, que usa una PC de escritorio conectada a un switch en el cuarto piso. ¿Qué servicio está realizando el DS?", "o": ["Asociación", "Integración", "Distribución", "Disociación", "Reasociación"], "c": [1], "why": "El origen está en Wi-Fi (802.11) y el destino en Ethernet (802.3). Integración es el servicio que convierte entre la red inalámbrica y una red de otro tipo. Ojo: Distribución lleva los datos de un AP a otro AP para llegar a otra estación inalámbrica; acá el destino es cableado.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t6", "pr": false, "q": "¿Qué servicios del sistema de distribución permiten que un dispositivo inalámbrico se desplace dentro del DS? (elegí dos)", "o": ["Distribución", "Asociación", "Integración", "Reasociación", "Disociación"], "c": [1, 3], "why": "Para moverse, la estación primero se asocia a un AP y, al pasar a la zona de otro, se reasocia con el nuevo. Así el DS sabe siempre en qué AP está. Ojo: Distribución traslada los datos entre AP, pero no es lo que habilita el desplazamiento de la estación.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t6", "pr": false, "q": "De acuerdo a la información obtenida de un análisis espectral realizado con el programa inSSIDer; ¿en qué canal convendría ubicar a su Access Point para minimizar la interferencia con sus vecinos?", "o": ["6", "4", "1", "11", "7"], "c": [3], "img": "p88", "why": "En 2,4 GHz los canales se pisan entre sí; los únicos que no se superponen son el 1, el 6 y el 11. De esos tres conviene el menos ocupado, que acá es el 11. Ojo: El 4 y el 7 parecen libres, pero se superponen con canales ocupados (el 4 con el 1 y el 6; el 7 con el 6). Con la figura real: La captura real confirma la respuesta: en el canal 1 están ARF (−50 dBm) y Belkin (−81/−82 dBm); en el 6, WLAN_77 (−50 dBm), Mike83 (−87) y otra WLAN_77 (−91); del 8 al 14 no hay nada. Se puede quitar «dudosa».", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t6", "pr": false, "q": "Término utilizado para designar una red inalámbrica en donde las estaciones pueden intercambiar datos directamente sin necesidad de instalar ningún elemento extra de infraestructura", "o": ["Tipo", "hoc ac", "Ninguna es correcta", "ping -c", "ad hoc"], "c": [4], "why": "En modo ad hoc las estaciones inalámbricas se comunican directamente entre sí, sin access point ni otra infraestructura. «hoc ac» es una inversión de letras puesta como trampa, y el modo con AP se llama infraestructura.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t6", "pr": false, "q": "¿Cuál es la principal desventaja del uso de una WLAN (frente a una LAN cableada)?", "o": ["Rapidez de instalación y configuración", "Seguridad", "Cantidad de estaciones de trabajo", "Inestabilidad de la conexión", "Costo inicial"], "c": [1], "why": "Según las filminas de WLAN, la ventaja es el costo y la desventaja es la seguridad: la señal de radio sale del edificio y cualquiera dentro del alcance puede intentar captarla. El costo inicial y la rapidez de instalación son ventajas, no desventajas.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t6", "pr": false, "q": "Frecuencias en tecnología inalámbrica: ¿en qué bandas trabajan las redes WLAN IEEE 802.11 (Wi-Fi)? (elegí dos)", "o": ["2,4 GHz", "5 GHz", "100 MHz", "50 GHz", "13,56 MHz"], "c": [0, 1], "why": "Wi-Fi usa las bandas libres de 2,4 GHz (802.11b/g/n, más alcance y más interferencia, canales 1, 6 y 11 sin solaparse) y de 5 GHz (802.11a/n/ac, más velocidad y canales, menos alcance).", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t6", "pr": false, "q": "Servicios del Sistema de distribución IEEE 802.11: ¿cuál de los siguientes es un servicio de distribución?", "o": ["Cifrado", "Resolución ARP", "Autenticación", "Integración", "Asignación DHCP"], "c": [3], "why": "Los servicios del sistema de distribución son asociación, desasociación, reasociación, distribución e integración (esta última conecta la WLAN con una red que no es 802.11, como Ethernet). Ojo: autenticación y cifrado (privacidad) también son de 802.11, pero son servicios de la estación, no del sistema de distribución. ARP y DHCP no son servicios de 802.11.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t6", "pr": false, "q": "Servicios de Distribución: ¿cuál de los siguientes es un servicio de distribución de IEEE 802.11?", "o": ["Servicios DNS", "Enrutamiento estático", "Asociación", "Traducción NAT", "Autenticación WPA"], "c": [2], "why": "La asociación vincula una estación con un AP y es uno de los servicios del sistema de distribución (junto con desasociación, reasociación, distribución e integración). Ojo: la autenticación es un servicio de la estación; DNS, enrutamiento y NAT no son servicios de 802.11.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t6", "pr": false, "q": "Tecnología inalámbrica, ¿cuál es el problema cuando los nodos o estaciones, por tener un alcance limitado, no se perciben entre sí por estar en diferentes áreas de alcance?", "o": ["Problema Terminal Oculta", "Problema Autenticación", "Problema Terminal Expuesto", "Problema de Integridad", "Problema AP expuesto"], "c": [0], "why": "Dos estaciones fuera del alcance mutuo no se escuchan, así que las dos «sienten» el canal libre y transmiten a la vez al mismo AP: chocan en el receptor. Eso es la terminal oculta, y RTS/CTS lo ataca. Ojo: la terminal expuesta es al revés: una estación escucha a otra y se abstiene de transmitir sin necesidad.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t6", "q": "Servicios del Sistema de Distribución IEEE 802.11 (seleccione 2):", "o": ["Cifrado", "Resolución ARP", "Autenticación", "Integración", "Asignación DHCP", "Asociación"], "c": [3, 5], "why": "Los servicios del DS son asociación, disociación, reasociación, distribución e integración.", "src": "Preguntas 4K1", "pr": false},
{"b": "t7", "pr": false, "q": "¿Cuántos bits tiene una dirección IPv4?", "o": ["128", "16", "32", "64", "48"], "c": [2], "why": "IPv4 usa 32 bits, escritos como 4 octetos de 8 bits separados por puntos; por eso cada número va de 0 a 255. Ojo: 48 bits es la dirección MAC, no la IP.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "¿Cómo se determina la clase de una dirección IPv4?", "o": ["Por la máscara de subred configurada", "Por el valor del primer byte", "Por el valor del último byte", "Por la puerta de enlace predeterminada", "Por la cantidad de hosts conectados a la red"], "c": [1], "why": "En el direccionamiento por clases, el primer octeto fija la clase: 1–126 es A, 128–191 es B y 192–223 es C. La clase define después la máscara por defecto, no al revés. Ojo: La máscara no define la clase: una clase B dividida en subredes con /24 sigue siendo clase B.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": true, "q": "¿Cuál es la función de la máscara en una dirección IPv4?", "o": ["Determinar la clase de la dirección", "Identificar la dirección MAC del host", "Determinar la porción de red", "Ocultar la dirección IP privada al salir a Internet", "Indicar cuál es la puerta de enlace"], "c": [2], "why": "Los bits en 1 de la máscara marcan qué parte de la IP es red (y subred); los bits en 0, qué parte es host. Así el equipo sabe si un destino está en su propia red. Ojo: La clase sale del primer octeto, no de la máscara.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": true, "q": "Si se hace el AND booleano entre la dirección IP de una PC y su máscara de subred, ¿qué se obtiene?", "o": ["La dirección de broadcast de la subred", "La dirección MAC de la PC", "La dirección de la puerta de enlace", "La dirección de la subred a la que pertenece la PC", "La cantidad de hosts de la subred"], "c": [3], "why": "Donde la máscara tiene 1, el AND conserva el bit de la IP; donde tiene 0, lo pone en 0. Queda la parte de red con la parte de host en ceros: la dirección de la subred. Ojo: El broadcast tiene la parte de host en unos, y el AND la deja en ceros.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial · Lista que pasaste (23/11) (preguntero web)"},
{"b": "t7", "pr": false, "q": "¿Cuál de las siguientes características corresponde al protocolo IPv4?", "o": ["Entrega los paquetes en orden usando números de secuencia", "Usa direcciones de 48 bits", "Es no orientado a conexión", "Establece un circuito virtual antes de enviar los datos", "Retransmite los paquetes perdidos"], "c": [2], "why": "IP manda cada paquete por separado, sin establecer una conexión previa y sin garantizar entrega ni orden. Retransmitir y ordenar lo hace TCP, en la capa de transporte. Ojo: Los números de secuencia y las retransmisiones son de TCP, no de IP.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "Completá: «El protocolo IP NO prevé mecanismos de control de flujo extremo a extremo, como tampoco ___ de los mensajes, dejando estas funciones en protocolos de la capa de ___».", "o": ["Secuenciación; Acceso a red", "Secuenciación; Transporte", "Tamaño máximo; Física", "Secuenciación; Física", "Tipo de servicio; Transporte"], "c": [1], "why": "Ordenar los mensajes (secuenciación) y controlar el flujo de punta a punta son tareas de transporte, por ejemplo de TCP. IP sí maneja direccionamiento, tipo de servicio y fragmentación. Ojo: «Tipo de servicio» no va: IP sí lo prevé, es un campo de su propia cabecera.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": true, "q": "Se necesita configurar 3 hosts con direcciones IP que puedan ser enrutadas a través de Internet. ¿Cuáles de las siguientes direcciones cumplen? (elegí tres)", "o": ["198.234.255.95", "181.0.0.1", "192.168.23.252", "172.64.12.0", "172.16.223.125"], "c": [0, 1, 3], "why": "En Internet solo se enrutan direcciones públicas; las privadas (10.x, 172.16 a 172.31, 192.168.x) quedan dentro de la organización. 172.64 está fuera del bloque 172.16–172.31. Ojo: 172.64.12.0 parece inválida por terminar en 0, pero en su red clase B (172.64.0.0/16) no es ni la red ni el broadcast: es un host.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "¿Cuál es el rango de direcciones privadas definidas en el RFC 1918? (elegí tres)", "o": ["172.16.0.0 hasta 172.31.255.255", "10.0.0.0 hasta 10.255.255.255", "192.168.0.0 hasta 192.168.255.255", "127.0.0.0 hasta 127.255.255.255", "172.16.0.0 hasta 172.16.255.255"], "c": [0, 1, 2], "why": "El RFC 1918 reserva una red clase A (10), 16 redes clase B (172.16 a 172.31) y 256 redes clase C (192.168.0 a 192.168.255). Esos bloques no se enrutan en Internet. Ojo: 172.16.0.0–172.16.255.255 se queda corto: el bloque privado de clase B llega hasta 172.31.255.255. Y 127 es loopback, no privada.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "¿Cuáles de las siguientes son direcciones públicas? (elegí tres)", "o": ["11.10.10.16", "172.20.60.8", "192.168.21.56", "172.14.60.8", "190.168.21.56"], "c": [0, 3, 4], "why": "Una dirección es pública si no cae en los bloques del RFC 1918. 172.14 queda antes de 172.16, 190.168 no es 192.168 y 11.x no es 10.x. Ojo: 190.168.21.56 se parece a 192.168, pero el primer octeto es 190: es pública.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "¿Qué direcciones podrías asignar a los equipos para que tengan conectividad a Internet? (elegí tres)", "o": ["11.10.10.10", "194.168.10.6", "172.31.60.90", "172.32.60.90", "192.168.10.6"], "c": [0, 1, 3], "why": "Para salir a Internet sin traducción hace falta una dirección pública. 172.32 ya está fuera del bloque privado 172.16–172.31, 11.x no es 10.x y 194.168 no es 192.168. Ojo: 172.31.60.90 parece pública, pero 172.31 es el último bloque privado de clase B.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "Respecto del direccionamiento IPv4 privado (RFC 1918), ¿qué afirmación es correcta?", "o": ["Hay 16 redes clase A privadas: de 10.0.0.0 a 25.0.0.0", "Hay 16 redes clase B privadas: de 172.16.0.0 a 172.31.0.0", "Hay 256 redes clase B privadas: de 172.0.0.0 a 172.255.0.0", "Las redes 172.16.0.0 a 172.31.0.0 son públicas", "Hay una sola red clase C privada: 192.168.0.0"], "c": [1], "why": "El RFC 1918 reserva 1 red clase A (10.0.0.0), 16 redes clase B (172.16 a 172.31) y 256 redes clase C (192.168.0 a 192.168.255). Ojo: 192.168 no es una sola red: son 256 redes clase C, de 192.168.0.0 a 192.168.255.0.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Forms PDF 1 (preguntero web)"},
{"b": "t7", "pr": false, "q": "Un administrador configura a mano 5 puestos de trabajo de una misma red y, por error, en uno no pone la puerta de enlace. ¿Se pueden comunicar entre ellos?", "o": ["Solo se comunican los 4 que tienen puerta de enlace; el quinto queda aislado", "El que no tiene puerta de enlace solo se puede comunicar con Internet", "Sí, todos se comunican entre ellos", "No, ninguno se comunica hasta que se corrija el error"], "c": [2], "why": "Para hablar con equipos de su misma red, la PC entrega directo en la LAN. La puerta de enlace solo se usa cuando el destino está en otra red. Ojo: La PC sin puerta de enlace no queda aislada: solo pierde la salida a otras redes, como Internet.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": true, "q": "Un router recibe por una de sus interfaces un paquete cuya dirección de destino es 255.255.255.255. ¿Qué hace?", "o": ["Lo reenvía solo por la interfaz serial hacia el ISP", "No lo reenvía a otras redes: es una difusión limitada a la red local", "Lo retransmite por todas sus interfaces menos por la que ingresó", "Lo reenvía hacia su puerta de enlace predeterminada"], "c": [1], "why": "255.255.255.255 es la difusión limitada: vale solo dentro de la red local. El router separa dominios de broadcast, así que no la pasa a otras redes. Ojo: Reenviar por todas las bocas menos la de entrada es lo que hace un hub o un switch con un broadcast, no un router.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Forms PDF 1 (preguntero web)"},
{"b": "t7", "pr": true, "q": "Un router tiene dos interfaces FastEthernet y una serial, todas con MTU de 1500 bytes, y recibe un paquete de 1000 bytes. ¿Qué hace para enviarlo?", "o": ["Le pide al origen que lo vuelva a enviar más chico", "Lo fragmenta en paquetes de 576 bytes", "Lo descarta porque supera la MTU", "Lo encapsula en una trama, sin fragmentarlo", "Lo fragmenta en dos paquetes de 500 bytes"], "c": [3], "why": "La MTU es el tamaño máximo de paquete que entra en una trama. Como 1000 bytes es menos que 1500, entra entero: el router solo lo encapsula en la trama de la interfaz de salida. Ojo: Fragmentar solo hace falta cuando el paquete supera la MTU; acá sobra lugar.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": true, "q": "De acuerdo con la siguiente captura de tráfico realizada con el programa Wireshark, podemos observar en pantalla que (seleccione 5 opciones)", "o": ["El host de destino estaba a 12 saltos del host origen", "El host de destino respondió con un paquete de ICMP Echo Replay con un TTL igual a 53", "El host de destino respondió con un paquete de ICMP Echo Replay con un TTL igual a 65 que se fue decrementando por cada nodo por el que pasó", "El protocolo que se utilizó es de capa de Interred", "El comando que se ejecutó en el host origen fue icmp config", "El host de origen está en Internet y el host de destino está en una LAN", "El host de origen está en una LAN y el host de destino está en Internet", "El host de destino estaba a 53 saltos del host origen", "El protocolo que se utilizó es de capa de Transporte", "El comando que se ejecutó en el host origen fue tracert"], "c": [0, 2, 3, 6, 9], "img": "fig_11", "why": "Los Echo Request con respuestas «Time-to-live exceeded» de cada router son la huella de tracert, que usa ICMP, un protocolo de la capa interred. El origen 192.168.1.10 es una IP privada de una LAN y el destino 190.224.160.74 es una IP pública de Internet. Según la clave de la UV, el destino estaba a 12 saltos y respondió con un TTL que se fue decrementando en cada router; «53 saltos» confunde el valor del TTL con la cantidad de saltos.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "Dos máquinas de la misma red realizan una consulta fuera de su LAN. El primer paquete que llega al router, es el de la máquina A y luego de B. Por algún motivo el router procesa primero el paquete de la máquina B y luego de A. ¿En qué campo del datagrama IPv4 se fijó el router para que realice esa acción?", "o": ["TTL", "Versión", "IHL", "Servicios Diferenciados", "Protocolo"], "c": [3], "why": "El campo Servicios Diferenciados (el antiguo Tipo de Servicio) marca la prioridad o clase de servicio del paquete, y el router lo usa para atender antes a un paquete que llegó después. El TTL solo limita los saltos, e IHL y Protocolo describen la cabecera y el contenido.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "Un paquete para su correcta transmisión, se divide en 3 fragmentos.   ¿Cuál de las siguientes afirmaciones es correcta con respecto al protocolo IPv4?", "o": ["Todos los fragmentos tendrán diferente número de identificación y el mismo protocolo", "Todos los fragmentos tendrán la misma suma de verificación y el mismo protocolo", "Todos los fragmentos tendrán el mismo número de Identificación y el mismo protocolo", "Todos los fragmentos tendrán el mismo desplazamiento y diferente Identificación", "Todos los fragmentos tendrán la misma dirección origen y destino, pero diferente identificación"], "c": [2], "why": "Todos los fragmentos de un mismo paquete llevan el mismo número de Identificación, para que el destino sepa que van juntos, y el mismo Protocolo, origen y destino. Lo que cambia es el desplazamiento de cada fragmento, y por eso también cambia la suma de verificación de la cabecera.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "Cuál de los siguientes campos pertenece a la cabecera de un paquete IPv4", "o": ["Siguiente cabecera", "Longitud de la cabecera", "Time to live", "Longitud de carga util", "Limite de salto"], "c": [1, 2], "why": "La cabecera IPv4 tiene «Longitud de la cabecera» (IHL) y «Time to live». «Siguiente cabecera», «Longitud de carga útil» y «Límite de saltos» son campos de la cabecera IPv6 (el último reemplaza al TTL).", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "Un router recibe por una de sus interfaces un paquete cuya dirección destino es 255.255.255.255. ¿Qué hará el router con dicho paquete?:", "o": ["Se lo envía al servidor de la LAN", "Lo encapsula en una trama", "Lo procesa", "Se lo envia a todas las PC de la LAN", "Lo descarta", "Se lo envia al switch de la LAN", "Lo retransmite por todas sus interfaces, menos por la que ingresó"], "c": [2], "why": "255.255.255.255 es la difusión limitada: va dirigida a todos los equipos de la red local, y el router, como integrante de esa red, la recibe y la procesa, pero nunca la reenvía a otras redes porque separa dominios de broadcast. Retransmitirla por todas las interfaces menos la de entrada es lo que hace un switch con un broadcast, no un router.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "Los campos de la cabecera del Internet Control Message Protocol sol", "o": ["Tipo, TTL y suma de verificacio", "Tipo, Código y suma de verificación", "Tipo, código, TTL, versión y suma de verificación", "Versión, TTL, Tipo, Código"], "c": [1], "why": "La cabecera ICMP tiene tres campos fijos: Tipo (qué clase de mensaje es), Código (el detalle dentro de ese tipo) y suma de verificación. TTL y versión son campos de la cabecera IP que lo transporta, no de ICMP.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "Cual de las siguientes caracteristicas corresponde al protocolo IPv4", "o": ["Retransmite el paquete que no llegó correctamente", "Utiliza direcciones de 48 bits", "Encamina cada paquete de manera independiente", "Reordena los paquetes en el destino", "Utiliza números de secuencias"], "c": [2], "why": "IPv4 es un servicio de datagramas no orientado a conexión: cada paquete se encamina por separado y puede seguir otro camino. Retransmitir, reordenar y usar números de secuencia es tarea de TCP (transporte), y las direcciones de 48 bits son las MAC.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "Los mensajes ICMP se envían utilizando el encabezado IP básico", "o": ["Verdadero", "Falso"], "c": [0], "why": "Los mensajes ICMP viajan dentro de un datagrama IP común: llevan el encabezado IP básico con el campo Protocolo en 1. ICMP pertenece a la capa interred, pero se encapsula en IP como cualquier otro dato.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "Las tablas ARP", "o": ["Pueden tener entradas dinamicas y estaticas", "Poseen solo entradas estaticas", "Necesitan configuración de las entradas dinamicas", "Tienen sólo entradas dinamicas"], "c": [0], "why": "La tabla ARP guarda pares IP–MAC. Las entradas dinámicas se aprenden solas con ARP request/reply y vencen con el tiempo; las estáticas las carga a mano el administrador. Las dinámicas no requieren configuración.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "¿Cuando un router descarta un paquete IP?", "o": ["Cuando su TTL llegó a 255", "Cuando el tamaño es menor a 1460 Bytes", "Cuando el campo ToS no está marcado", "Cuando no trae la máscara de subred", "Cuando su TTL llega a cero"], "c": [4], "why": "Cada router le resta 1 al TTL; cuando llega a cero descarta el paquete (y avisa al origen con un ICMP de tiempo excedido) para que no circule para siempre en un bucle. 255 es el valor máximo inicial del TTL, no un motivo de descarte, y la máscara no viaja en el paquete.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "Es utilizado para enviar mensajes de error e información operativa, como por ejemplo", "o": ["El destino recibió un paquete duplicado", "El destino recibió un paquete con errores en los datos", "el ancho de banda de línea no es suficiente para transmitir  ese datagrama", "Un host no puede ser localizado", "La conexión está muy lenta", "Un router avisa al host origen de algún problema en el procesamiento del datagrama", "Un datagrama ya pasó por varios routers y al no encontrar el destino, debe ser descartado", "Un router no tiene suficiente espacio en su memoria para alojar el datagrama que recibió y debe descartarlo"], "c": [3, 5, 6, 7], "why": "ICMP lleva mensajes de error y de control de la capa interred: destino inalcanzable (host no localizado), TTL agotado tras pasar por varios routers, problemas de procesamiento en un router y falta de memoria para alojar el datagrama. No informa errores en los datos, duplicados, ancho de banda ni lentitud: eso no es tarea de IP ni de ICMP.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "Cual de los siguientes protocolos permite que una PC obtenga una dirección IPv4 a partir de su dirección MAC, debiendo configurar tablas con mapeos estáticos y permanentes en el servidor y requiriendo que la PC esté siempre en la misma LAN que el servidor", "o": ["Reverse address resolution Protocol", "Internet Protocol", "Bootstrap Protocol", "Dynamic Host Configuration Protocol Version 6", "Adress Resolution Protocol"], "c": [0], "why": "RARP hace lo inverso de ARP: a partir de la MAC obtiene una IPv4, pero necesita tablas estáticas cargadas en un servidor de la misma LAN. BOOTP y DHCP lo reemplazaron porque pueden atravesar routers (y DHCP asigna dinámicamente); ARP va de IP a MAC.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t7", "pr": false, "q": "Una máscara de red/subred está formada por:", "o": ["Unos en la parte de red y subred, y ceros en la parte de host", "Unos en la parte de red y subred, y unos en la parte de host", "Ceros en la parte de red y unos en la parte de host", "Unos solo en la parte de host", "La dirección de red con el último octeto en 255"], "c": [0], "why": "La máscara marca con 1 los bits que identifican la red (y la subred, si se pidieron bits prestados) y con 0 los bits de host. Por eso el AND con la IP deja la dirección de red. Ojo: «unos en la parte de host» sería 255.255.255.255, que no deja lugar para hosts.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t7", "pr": false, "q": "Para que una computadora posea conectividad (a otras redes e Internet, usando nombres), debe tener configurado: (elegí cuatro)", "o": ["Dirección IP", "Máscara de subred", "Puerta de enlace predeterminada", "Servidor DNS", "Dirección MAC del router", "Número de puerto del servidor"], "c": [0, 1, 2, 3], "why": "La IP identifica a la PC, la máscara le dice qué direcciones son de su red, la puerta de enlace es a quién mandarle lo que va a otras redes y el DNS traduce nombres a IP. La MAC del router la averigua sola con ARP, y los puertos los elige cada aplicación: no se configuran.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t7", "pr": false, "q": "127.5.5.5, ¿es una dirección localhost (loopback)?", "o": ["Verdadero", "Falso"], "c": [0], "why": "Todo el bloque 127.0.0.0/8 está reservado para loopback, no solo 127.0.0.1: cualquier dirección 127.x.x.x vuelve a la propia máquina y nunca sale a la red. Por eso la clase A útil va de 1 a 126.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t7", "pr": false, "q": "¿Qué es el Gateway por defecto (puerta de enlace predeterminada)?", "o": ["La dirección IP de la interfaz del router de la red local, a la que la PC envía lo que va a otras redes", "La dirección IP de la interfaz del switch a la que está conectada la PC", "La dirección MAC de la placa de red de la PC", "La dirección IP del servidor DNS", "La dirección de broadcast de la subred"], "c": [0], "why": "Cuando el destino no está en su red, la PC le entrega el paquete a la puerta de enlace: la interfaz del router que está en su misma red, y el router lo encamina. Ojo: el switch es de capa 2 y no encamina entre redes, así que no puede ser la puerta de enlace.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t7", "pr": true, "q": "El prefijo /18 equivale a cuál de las máscaras de subred:", "o": ["255.255.192.0", "255.255.128.0", "255.255.224.0", "255.255.255.192", "255.192.0.0"], "c": [0], "why": "/18 son 18 unos: 8 + 8 completan los dos primeros octetos (255.255) y quedan 2 unos en el tercero: 11000000 = 128 + 64 = 192. Máscara: 255.255.192.0. Ojo: 255.255.255.192 es /26 (los 2 unos en el cuarto octeto).", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t7", "q": "El algoritmo para determinar el Checksum de IPv4 se calcula:", "o": ["En cada salto y en el destino", "No existe ese campo en la cabecera", "En el origen, en el destino y una vez en cada salto", "En el origen, en el destino y dos veces en cada salto", "Sólo en el destino"], "c": [3], "why": "El checksum cubre solo la cabecera. En cada router se calcula dos veces: una para verificar la cabecera que llega y otra para recalcularlo, porque el router cambió el TTL. Más el origen (lo genera) y el destino (lo verifica).", "src": "Revisión en clase del 1er parcial", "pr": false},
{"b": "t7", "q": "Un mensaje ARP-reply se encapsula en:", "o": ["Un paquete con dirección destino 255.255.255.255", "Un paquete con dirección destino unicast", "Una trama con dirección destino unicast", "Una trama con dirección destino multicast", "Una trama con dirección destino FF:FF:FF:FF:FF:FF"], "c": [2], "why": "ARP va directo sobre la trama (no en un paquete IP). El request es broadcast; el REPLY es unicast al que preguntó.", "src": "Revisión en clase del 1er parcial (2020)", "pr": false},
{"b": "t7", "q": "La dirección MAC destino en una trama enviada desde una PC que está arrancando hacia un servidor DHCP es:", "o": ["FF-FF-FF-FF-FF-FF", "0.0.0.0", "1111-1111-1111-1111", "Dirección IP del servidor DHCP", "255.255.255.255"], "c": [0], "why": "El DHCP Discover va en broadcast: MAC destino FF-FF-FF-FF-FF-FF e IP destino 255.255.255.255 (IP origen 0.0.0.0). Pregunta por la MAC → FF-FF...", "src": "Revisión en clase del 1er parcial (2020)", "pr": false},
{"b": "t7", "q": "La dirección IP destino en un paquete enviado desde una PC que está arrancando hacia un servidor DHCP es:", "o": ["Dirección IP del servidor DHCP", "255.255.255.255", "FF-FF-FF-FF-FF-FF", "1111-1111-1111-1111", "0.0.0.0"], "c": [1], "why": "IP destino del Discover = 255.255.255.255 (broadcast limitado); la PC todavía no conoce al servidor. 0.0.0.0 es la IP ORIGEN.", "src": "Revisión en clase del 1er parcial (2020)", "pr": false},
{"b": "t7", "q": "El agente relay DHCP se ejecuta cuando:", "o": ["Cliente y servidor Web se encuentran en diferentes subredes", "Cliente y servidor DHCP están en la misma subred", "Existe un servidor DHCP en cada subred", "Cliente y servidor DHCP se encuentran en diferentes subredes"], "c": [3], "why": "El broadcast del Discover no atraviesa routers; el relay (ip helper-address en el router) lo reenvía en unicast al servidor DHCP de otra subred.", "nota": "En la captura alguien marcó 'misma subred', que es justamente cuando NO hace falta relay.", "src": "Revisión en clase del 1er parcial (2020)", "pr": false},
{"b": "t8", "pr": true, "q": "Con una estructura N.N.H.H hay que crear subredes, minimizando la cantidad de subredes. ¿De dónde se piden prestados los bits?", "o": ["Del tercer octeto, de derecha a izquierda", "Del tercer octeto, de izquierda a derecha", "Del cuarto octeto, de derecha a izquierda", "Del segundo octeto, de izquierda a derecha", "Del cuarto octeto, de izquierda a derecha"], "c": [1], "why": "En N.N.H.H la parte de host empieza en el tercer octeto. Los bits de subred se toman de la parte de host empezando por la izquierda, pegados a la red, para que la máscara quede con unos seguidos. Ojo: Tomarlos de derecha a izquierda dejaría ceros en medio de la máscara, y la máscara tiene que ser unos seguidos de ceros.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "Una empresa está dividida en 10 áreas de trabajo y decide implementar un esquema de direccionamiento IP con subredes. ¿Qué afirmación es correcta?", "o": ["Cada área tendrá una máscara distinta según su cantidad de hosts", "La máscara de subred puede ser más corta que la máscara por defecto de la clase", "Se necesitan 10 bits de subred, uno por área", "Todas las subredes deben tener la misma máscara de subred", "Con 3 bits de subred alcanza para las 10 áreas"], "c": [3], "why": "En el esquema de subredes (máscara fija), todas las subredes usan la misma máscara y tienen la misma cantidad de hosts. Para 10 áreas hacen falta 4 bits (2⁴ = 16 ≥ 10). Ojo: Una máscara distinta por área es VLSM, que es otra técnica: subredes dentro de subredes.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "Un administrador de red subneteó la red 172.16.0.0 con la máscara 255.255.255.224. Por error duplicó la IP 172.16.2.121 en 2 equipos de la misma subred. ¿Qué IP podría asignarse en reemplazo de la duplicada?", "o": ["172.16.2.127", "172.16.1.80", "172.16.2.96", "172.16.2.100", "172.16.2.128"], "c": [3], "why": "255.255.255.224 es /27: bloques de 32 en el 4.º octeto (0, 32, 64, 96, 128…). La .121 cae en 172.16.2.96–127: red .96, hosts .97 a .126, broadcast .127. La .100 está en ese rango de hosts. Ojo: .96 y .127 están en el bloque correcto, pero son la red y el broadcast: no se asignan a equipos.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "Tu ISP te asignó un espacio completo de clase C pública. Tenés que armar 3 subredes que soporten 60 hosts cada una. ¿Cuáles de las siguientes son direcciones de red que cumplen ese requisito? (elegí tres)", "o": ["193.16.2.0", "192.16.2.127", "255.255.255.192", "193.16.2.128", "193.16.2.64"], "c": [0, 3, 4], "why": "60 hosts piden 6 bits de host (2⁶ − 2 = 62). En una clase C quedan 2 bits de subred: /26, en saltos de 64. Las redes son .0, .64, .128 y .192. Ojo: 255.255.255.192 es la máscara de esas subredes, no una dirección de red.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "Tu ISP te asignó el espacio completo de clase C pública 193.16.2.0 y armás 3 subredes que soporten 60 hosts cada una. ¿Cuáles de las siguientes son direcciones de host válidas? (elegí tres)", "o": ["193.16.2.120", "193.16.2.1", "193.16.2.65", "192.16.2.65", "255.255.255.192"], "c": [0, 1, 2], "why": "Con /26 los bloques son .0–.63, .64–.127, .128–.191 y .192–.255. Es host cualquier dirección que no sea la primera (red) ni la última (broadcast) de su bloque: .1, .65 y .120 cumplen. Ojo: 192.16.2.65 tiene el último octeto correcto, pero es de otra red (192.16.2, no 193.16.2).", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t8", "pr": true, "q": "Para la siguiente topología de red, determinar las máscaras que podrían usarse para satisfacen los requisitos de direcciones de host en cada subred", "o": ["Córdoba /27, Río Cuarto /26, Villa María /25, enlaces WAN /30", "Córdoba /26, Río Cuarto /27, Villa María /28, enlaces WAN /30", "Córdoba /24, Río Cuarto /24, Villa María /24, enlaces WAN /24", "Córdoba /25, Río Cuarto /26, Villa María /27, enlaces WAN /30", "Córdoba /25, Río Cuarto /26, Villa María /27, enlaces WAN /24"], "c": [3], "img": "p108", "why": "En cada subred va la máscara más larga que alcance: 2⁷ − 2 = 126 ≥ 120 (/25), 2⁶ − 2 = 62 ≥ 60 (/26), 2⁵ − 2 = 30 ≥ 20 (/27). Un enlace punto a punto necesita 2 IP: 2² − 2 = 2 (/30). Ojo: /24 en los enlaces WAN gasta 254 direcciones para 2 routers y no entra junto con las demás subredes en el bloque. Con la figura real: La figura real dice Córdoba 120 hosts, Río Cuarto 60 y Villa María 20 (el texto actual dice 100 y 50). Las máscaras no cambian: /25, /26, /27 y /30 en los enlaces WAN. Conviene corregir los números del enunciado y de la explicación (2⁷ − 2 = 126 ≥ 120; 2⁶ − 2 = 62 ≥ 60).", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "Para la siguiente topología de red, ¿cuáles podrían ser las direcciones de la puerta de enlace predeterminada (default gateway) de las subredes de CORDOBA, RIO CUARTO y VILLA MARIA?", "o": ["Córdoba 192.168.16.0, Río Cuarto 192.168.16.128, Villa María 192.168.16.192", "Córdoba 192.168.16.1, Río Cuarto 192.168.16.65, Villa María 192.168.16.97", "Córdoba 192.168.16.1, Río Cuarto 192.168.16.1, Villa María 192.168.16.1", "Córdoba 192.168.16.1, Río Cuarto 192.168.16.129, Villa María 192.168.16.193"], "c": [3], "img": "p108", "why": "Córdoba /25 ocupa .0–.127 (primera válida .1). Río Cuarto /26 arranca en .128 y llega a .191 (primera válida .129). Villa María /27 arranca en .192 (primera válida .193). Ojo: .0, .128 y .192 son las direcciones de red: la puerta de enlace tiene que ser una IP de host. Con la figura real: Misma figura que P108. Correcta oficial UV: Córdoba 192.168.16.1, Río Cuarto 192.168.16.129, Villa María 192.168.16.193 (sin cambio). Ojo: choca con F115, donde la UV da como hosts de Villa María .226, .227 y .238 (de la .224/27); la figura no indica en qué orden se asignan los enlaces WAN, así que no lo resuelve.", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t8", "pr": true, "q": "Se arman subredes con la IP 195.64.15.0/28. ¿Qué implica?", "o": ["Se pierden 2 direcciones del total del espacio", "Se pierden 16 direcciones del total del espacio", "Se pierden 32 direcciones del total del espacio", "Se obtienen 28 subredes", "Se obtienen 16 subredes de 16 hosts válidos cada una"], "c": [2], "why": "195 es clase C (/24), así que /28 toma 4 bits: 2⁴ = 16 subredes. Cada subred pierde 2 direcciones (red y broadcast): 16 × 2 = 32. Ojo: «16 hosts válidos» olvida restar la red y el broadcast: son 2⁴ − 2 = 14.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "Se arman subredes con la IP 160.4.0.0/23. ¿Qué implica?", "o": ["Se obtienen 7 subredes", "Se obtienen 64 subredes", "Se pierden 2 direcciones del total del espacio", "Se pierden 256 direcciones del total del espacio", "Se pierden 128 direcciones del total del espacio"], "c": [3], "why": "160 es clase B (/16): /23 toma 7 bits, 2⁷ = 128 subredes. Cada una pierde la red y el broadcast: 128 × 2 = 256. Ojo: 128 es la cantidad de subredes; las direcciones perdidas son el doble.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "¿Cuál es la máxima cantidad de bits que se pueden pedir prestados para subredes en una dirección clase A?", "o": ["22", "24", "30", "8", "23"], "c": [0], "why": "Clase A tiene 24 bits de host. Hay que dejar al menos 2 para hosts (2² − 2 = 2 hosts). Entonces se pueden prestar 24 − 2 = 22. Ojo: 30 es el prefijo final (/30), no los bits prestados: hay que restarle los 8 bits de red de la clase A.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "Hay que armar 20 subredes maximizando la cantidad de hosts por subred. ¿Qué direcciones cumplen? (elegí dos)", "o": ["190.60.0.0/24", "199.60.5.0/29", "190.60.0.0/20", "199.60.5.0/28", "190.60.0.0/21"], "c": [1, 4], "why": "20 subredes piden 5 bits (2⁵ = 32; con 4 bits serían 16). Usar los mínimos bits deja más hosts. Clase B: /16 + 5 = /21. Clase C: /24 + 5 = /29. Ojo: /20 y /28 usan 4 bits de subred: dan solo 16 subredes, no alcanzan para 20.", "src": "Forms PDF 3 (preguntero web)"},
{"b": "t8", "pr": true, "q": "El prefijo /28 equivale a la máscara:", "o": ["255.255.255.192", "255.255.255.240", "255.255.240.0", "255.255.255.224", "255.255.255.248"], "c": [1], "why": "/28 son 28 unos: 24 en los tres primeros octetos (255.255.255) y 4 en el último: 128 + 64 + 32 + 16 = 240. Ojo: 255.255.240.0 también tiene un 240, pero en el tercer octeto: es /20.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "¿Cuál es el rango de direcciones IP válidas de la subred 170.62.32.0/22?", "o": ["170.62.32.1 – 170.62.36.254", "170.62.32.1 – 170.62.35.254", "170.62.32.1 – 170.62.32.254", "170.62.32.1 – 170.62.39.254", "170.62.32.0 – 170.62.35.255"], "c": [1], "why": "/22 deja 10 bits de host: el bloque ocupa 4 valores del 3.er octeto (32 a 35). La red es 170.62.32.0 y el broadcast 170.62.35.255; los hosts van de la siguiente a la red a la anterior al broadcast. Ojo: 170.62.32.0 – 170.62.35.255 incluye la red y el broadcast, que no se asignan a equipos.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "¿Cuál es el rango de direcciones válidas de la subred 189.45.8.0/25?", "o": ["189.45.8.0 – 189.45.8.127", "189.45.8.1 – 189.45.8.254", "189.45.8.0 – 189.45.8.255", "189.45.8.1 – 189.45.8.126", "189.45.8.1 – 189.45.8.127"], "c": [3], "why": "/25 deja 7 bits de host: 128 direcciones, de .0 a .127. La .0 es la red y la .127 el broadcast, así que los hosts van de .1 a .126. Ojo: .0 – .255 es el bloque /24 completo y, además, incluye la red y el broadcast.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": false, "q": "¿Cuáles de las siguientes son direcciones de broadcast? (elegí dos)", "o": ["100.50.51.255/22", "192.168.28.71/29", "172.16.4.127/24", "192.168.28.72/29", "100.50.48.255/22"], "c": [0, 1], "why": "/22 agrupa de a 4 en el 3.er octeto: 100.50.48.0 a 100.50.51.255, así que el broadcast es .51.255. /29 agrupa de a 8 en el 4.º: .64 a .71, broadcast .71. Ojo: 100.50.48.255 termina en 255, pero está en medio del bloque /22: es un host válido.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "El ISP te asigna la dirección 190.45.96.0/22. ¿Cuántas direcciones válidas para hosts tenés?", "o": ["1024", "1022", "2046", "510", "254"], "c": [1], "why": "/22 deja 32 − 22 = 10 bits de host: 2¹⁰ = 1024 direcciones. Se restan la red y el broadcast: 1022. Ojo: 1024 olvida restar la red y el broadcast.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "Tenés una red clase B pública y necesitás subredes de 28 hosts como máximo, maximizando la cantidad de subredes. ¿Qué afirmación es correcta?", "o": ["Se dejan 6 bits para host y el prefijo es /26", "Se dejan 5 bits para host y el prefijo es /27", "Se dejan 4 bits para host y el prefijo es /28", "Se dejan 5 bits para host y el prefijo es /21"], "c": [1], "why": "Para 28 hosts: 2⁵ − 2 = 30 alcanza y 2⁴ − 2 = 14 no. Dejar solo los bits de host necesarios maximiza las subredes: 32 − 5 = /27. Ojo: /21 suma los 5 bits a la máscara de clase B (16 + 5), pero esos 5 bits son de host, no de subred.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "¿Cuáles de las siguientes direcciones IP podrá utilizar un administrador de red, si desea implementar un esquema de direccionamiento IP con 20 subredes maximizando la cantidad de hosts por subred? (Seleccione dos)", "o": ["98.0.0.0/15", "100.0.0.0/14", "189.85.0.0/23", "4.199.60.50/29", "190.60.0.0/21", "140.56.0.0/22"], "c": [3, 4], "why": "Para 20 subredes hacen falta 5 bits (2⁵ = 32). En clase B queda /16 + 5 = /21, así que 190.60.0.0/21 cumple. En clase A daría /13 y en clase C /29: ninguna de las opciones de clase A tiene /13, y la opción «4.199.60.50/29» parece ser «199.60.5.0/29» (clase C, /24 + 5 = /29) copiada con el número de opción «4.» delante. /14, /15, /22 y /23 no corresponden a 5 bits sobre su clase.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t8", "pr": true, "q": "Se arman subredes con la IP 185.6.0.0/25. ¿Qué implica? Se pierden …. direcciones", "o": ["Se pierden 2 direcciones del total del espacio", "Se pierden 512 direcciones del total del espacio", "Se pierden 1024 direcciones del total del espacio", "Se pierden 256 direcciones del total del espacio", "Se obtienen subredes de 128 hosts válidos cada una"], "c": [2], "why": "185 es clase B (/16), así que /25 toma 9 bits: 2⁹ = 512 subredes. Cada subred pierde 2 direcciones (la de red y la de broadcast): 512 × 2 = 1024. Ojo: 512 es la cantidad de subredes, no las direcciones perdidas; y cada subred tiene 2⁷ − 2 = 126 hosts válidos, no 128.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t8", "pr": true, "q": "¿Cuáles son direcciones IP válidas para hosts de la red 150.150.192.0/22? (elegí dos)", "o": ["150.150.192.0", "150.150.193.255", "150.150.194.0", "150.150.195.255", "150.150.196.1"], "c": [1, 2], "why": "/22 deja 10 bits de host: el bloque va de 150.150.192.0 (red) a 150.150.195.255 (broadcast), así que los hosts van de .192.1 a .195.254. Por eso .193.255 y .194.0 son válidas aunque «terminen» en 255 o en 0: con /22 no son ni la red ni el broadcast. 150.150.196.1 ya es de la subred siguiente.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t8", "pr": true, "q": "¿Cuál es la dirección de broadcast de la subred 105.5.44.0/23?", "o": ["105.5.44.255", "105.5.45.255", "105.5.46.255", "105.5.47.255", "105.5.255.255"], "c": [1], "why": "/23 deja 9 bits de host: cada subred ocupa 2 valores del tercer octeto (salto 256 − 254 = 2). La subred 105.5.44.0 cubre 44 y 45, así que su broadcast es 105.5.45.255. Ojo: 105.5.44.255 es un host válido, no el broadcast.", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t8", "q": "Topología del parcial (red 192.168.16.0/24): CÓRDOBA necesita ~100 hosts, RÍO CUARTO ~50, VILLA MARÍA ~25 y hay enlaces WAN punto a punto. ¿Qué máscaras satisfacen los requisitos?", "filas": ["Córdoba", "Río Cuarto", "Villa María", "Enlaces WAN"], "o": ["/25", "/26", "/27", "/28", "/30"], "c": [0, 1, 2, 4], "why": "VLSM: 100 hosts → 7 bits (126) → /25; 50 → 6 bits (62) → /26; 25 → 5 bits (30) → /27; enlace punto a punto → 2 hosts → /30.", "nota": "La cantidad exacta de hosts de cada sede estaba en la figura del parcial (no la tenemos). La clave era Córdoba /25, Río Cuarto /26, Villa María /27, WAN /30.", "src": "Moodle 1er Parcial 4K4 (2020)", "pr": true},
{"b": "t8", "q": "¿Cuáles de las siguientes direcciones podrá utilizar un administrador que desea un esquema con 20 subredes, maximizando la cantidad de hosts por subred? (seleccione dos)", "o": ["140.56.0.0/22", "189.85.0.0/23", "100.0.0.0/14", "98.0.0.0/15", "190.60.0.0/21", "199.60.5.0/29"], "c": [2, 4], "why": "20 subredes → 5 bits prestados (32). Clase A /8 + 5 = /13; clase B /16 + 5 = /21; clase C /24 + 5 = /29. Válidas: 190.60.0.0/21 (B) y 199.60.5.0/29 (C). 100.0.0.0/14 y 98.0.0.0/15 son clase A pero con 6 y 7 bits (no maximizan hosts).", "nota": "En la captura las marcas finales eran /21 y /29. Coincide con el cálculo (clase B → /21, clase C → /29).", "src": "Revisión en clase del 1er parcial / FORMS Direcciones IP y Trama", "pr": true},
{"b": "t8", "q": "¿Cuántas direcciones IP válidas tiene 150.150.192.0/22?", "o": ["1022", "1024", "510", "254", "2046"], "c": [0], "why": "/22 deja 10 bits de host: 2^10 − 2 = 1022 (150.150.192.1 a 150.150.195.254).", "src": "Preguntas 4K1", "pr": true},
{"b": "t9", "pr": false, "q": "Los puertos de un switch que soporta VLAN: ¿qué emparejamiento es correcto?", "o": ["Puertos de acceso → etiquetado (tagged); puertos troncales (trunk) → etiquetado (tagged)", "Puertos de acceso → sin etiquetar (untagged); puertos troncales (trunk) → sin etiquetar (untagged)", "Puertos de acceso → etiquetado (tagged); puertos troncales (trunk) → sin etiquetar (untagged)", "Puertos de acceso → sin etiquetar (untagged); puertos troncales (trunk) → etiquetado (tagged)"], "c": [3], "why": "Un puerto de acceso pertenece a una sola VLAN y va a un equipo final, que no usa etiquetas. El troncal lleva tramas de varias VLAN entre switches, así que cada trama lleva la etiqueta 802.1Q que indica su VLAN. Ojo: Si el troncal no etiquetara, el switch del otro lado no podría saber a qué VLAN pertenece cada trama.", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t9", "pr": false, "q": "En la creación de VLAN estáticas:", "o": ["De acuerdo al protocolo del tráfico que envía el host, es la VLAN a la que va a pertenecer el puerto del switch", "De acuerdo al tipo de host (PC, teléfono IP, TV, tablet, etc.) será la VLAN a la que pertenezcan", "Un administrador debe crear la VLAN en el switch y luego agregar los puertos a ella", "A medida que las estaciones de trabajo se conectan a los puertos del switch, este les va asignando una de las VLAN que tiene disponibles", "El switch raíz les indica a los otros a qué VLAN pertenecen"], "c": [2], "why": "En las VLAN estáticas (basadas en el puerto) todo lo decide el administrador: crea la VLAN y le asigna puertos. El equipo que se conecte a ese puerto queda en esa VLAN. Ojo: Asignar la VLAN «a medida que se conectan» describe algo automático, más parecido a las VLAN dinámicas.", "src": "UV 2020 (revisiones) · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t9", "pr": false, "q": "Un administrador va a configurar VLAN dinámicas para una empresa a través de un servidor. ¿Cómo se denomina ese servidor?", "o": ["VMPS", "DHCP", "DNS", "FTP"], "c": [0], "why": "VMPS (VLAN Management Policy Server) tiene la base de datos que asocia cada MAC o usuario con su VLAN. Cuando un equipo se conecta, el switch le consulta en qué VLAN ponerlo. Ojo: DHCP asigna direcciones IP, no VLAN: actúa después, cuando el equipo ya está en su VLAN.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t9", "pr": false, "q": "¿Cuáles de las siguientes características corresponden a las VLAN? (elegí tres)", "o": ["Facilitan la implementación de seguridad", "Se implementan con el estándar IEEE 802.1D", "Todos los equipos de una VLAN deben estar conectados al mismo switch", "Se implementan mediante configuración en los switches", "Permiten agrupar a los empleados en forma lógica, sin importar su ubicación física"], "c": [0, 3, 4], "why": "Una VLAN es una red lógica armada en switches configurables: separa el tráfico (eso ayuda a la seguridad) y agrupa por función, no por lugar físico. Ojo: 802.1D es Spanning Tree; el estándar de VLAN es 802.1Q.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t9", "pr": false, "q": "¿Cuáles de las siguientes características corresponden a las VLAN? (elegí tres)", "o": ["Se implementan con el estándar IEEE 802.1Q", "Cada VLAN es un dominio de broadcast", "La etiqueta de VLAN se agrega en el paquete IP", "Si se definen 5 VLAN, se deben configurar 5 subredes", "Los switches se interconectan por puertos de acceso para transportar varias VLAN"], "c": [0, 1, 3], "why": "El broadcast de una VLAN no sale de ella, y cada VLAN necesita su propia red o subred. 802.1Q agrega la etiqueta de VLAN en los enlaces troncales. Ojo: La etiqueta 802.1Q va en la trama Ethernet (capa 2), no en el paquete IP.", "src": "Forms PDF 1 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t9", "pr": true, "q": "Los puertos del switch que soporta VLAN:", "o": ["B1", "B2", "No corresponde"], "filas": ["Etiquetado (tagedd)", "Etiquetado (tagged)", "Sin etiquetar (untagged)"], "c": [2, 1, 0], "img": "fig_18", "why": "Por un puerto de acceso (B1) pasa una sola VLAN, así que las tramas van sin etiquetar (untagged); por un troncal (B2) pasan varias VLAN y cada trama lleva la etiqueta 802.1Q (tagged). Las dos filas «Etiquetado» dicen lo mismo: una sobra, y se asume que la de la errata «tagedd» va a «No corresponde».", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t9", "pr": true, "q": "Indique cuántos dominios de broadcast existen en la figura", "o": ["1", "4", "3", "2", "Ninguna"], "c": [2], "img": "fig_02", "why": "Cada VLAN es un dominio de broadcast: en la figura hay tres VLAN (10 docentes, 20 estudiantes y 30 invitados), repartidas entre S2 y S3 y unidas por troncales. El router R1, con un solo enlace a S1, solo enruta entre ellas y no agrega otro dominio; la trampa es contestar «1» porque todos los switches están conectados entre sí.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t9", "q": "¿Cuáles de las siguientes características corresponden a las VLAN? (seleccione tres)", "o": ["Agrupan hosts lógicamente, independientemente de su ubicación física", "Aumentan el dominio de broadcast", "Reducen los dominios de broadcast (uno por cada VLAN)", "Necesitan un router por cada VLAN en cada piso", "Permiten implementar seguridad", "Solo funcionan con hubs"], "c": [0, 2, 4], "why": "Filmina 1-10: las VLAN agrupan lógicamente sin importar la ubicación física, cada VLAN es su propio dominio de broadcast (lo achican) y permiten implementar seguridad. Se implementan sobre switches configurables.", "src": "FORMS Direcciones IP y Trama / Filmina 1-10", "pr": false},
{"b": "t10", "pr": false, "q": "A un administrador de red le proponen configurar sumarización de rutas en el router. ¿Qué beneficio tiene?", "o": ["Elimina la necesidad de usar máscaras de subred", "Reduce el tamaño de las tablas de encaminamiento", "Permite usar direcciones privadas en Internet", "Aumenta la cantidad de direcciones IPv4 públicas disponibles", "Reduce los dominios de colisión de la LAN"], "c": [1], "why": "Sumarizar es anunciar varias redes contiguas con una sola ruta de prefijo más corto (por ejemplo, varias /24 como una /20). Hay menos entradas en la tabla y el router la procesa más rápido.", "src": "Teóricas 1.er parcial · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t10", "pr": false, "q": "¿Cuáles de las siguientes son características de VLSM? (elegí dos)", "o": ["Todas las subredes deben tener la misma máscara", "Para direccionar pocos hosts usa máscaras cortas", "Solo se puede usar con direcciones privadas", "Permite tomar una subred y volver a dividirla", "Para direccionar pocos hosts usa máscaras largas"], "c": [3, 4], "why": "VLSM (máscara de longitud variable) arma subredes dentro de subredes, cada una del tamaño justo. Máscara larga es pocos bits de host, o sea pocos hosts: ideal para enlaces punto a punto. Ojo: Una máscara corta deja muchos bits de host: sirve para muchos hosts, no para pocos.", "src": "Forms PDF 3 · Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t10", "pr": false, "q": "¿Qué partes forman una dirección unicast global IPv6?", "o": ["Prefijo de país, identificador de subred y número MAC", "Prefijo de zona geográfica mundial, cantidad de interfaces de un router e identificador de interfaz", "Prefijo de enrutamiento global, máscara de subred y broadcast", "Prefijo de enrutamiento global, identificador de subred e identificador de interfaz", "Prefijo de país, máscara de subred y número MAC"], "c": [3], "why": "La unicast global tiene tres partes: el prefijo global (la red que asigna el proveedor), el identificador de subred (las subredes internas) y el identificador de interfaz (el equipo). Ojo: Broadcast no puede ser: IPv6 no tiene direcciones de broadcast.", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t10", "pr": false, "q": "En una dirección IPv6, ¿cuántos bits se usan para identificar a la interfaz a la que pertenece?", "o": ["64", "48", "16", "128", "32"], "c": [0], "why": "Una IPv6 tiene 128 bits. El reparto típico es 48 de prefijo global, 16 de subred y 64 de interfaz; por eso las subredes suelen ser /64. Ojo: 48 bits es el prefijo global (y el tamaño de una MAC), no el identificador de interfaz.", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t10", "pr": false, "q": "Dada la dirección IPv6 2001:00ab:f000:0cde:0000:0000:1234:0000, ¿cuál es el formato correcto de la escritura comprimida?", "o": ["2001:ab:f:cde::1234:0", "2001:ab:f000:cde::1234", "2001:ab::cde::1234", "2001:ab:f000:cde::1234:0", "2001:0ab:f:0cde::1234:0"], "c": [3], "why": "Se sacan los ceros a la izquierda de cada grupo (00ab → ab, 0cde → cde), pero no los de la derecha (f000 queda igual). Un solo bloque de grupos en cero se cambia por «::» y el último 0000 queda como 0. Ojo: 2001:ab:f:cde::1234:0 recorta f000 a f: eso saca ceros de la derecha, y solo se pueden sacar los de la izquierda.", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t10", "pr": false, "q": "Un servidor tiene la dirección IPv6 2001::2460:34:0:980. ¿Qué dirección va en la cabecera del paquete, escrita completa?", "o": ["2001:0000:0000:2460:0034:0000:0980:0000", "2001:2460:0034:0000:0980:0000:0000:0000", "2001:0000:0000:0000:2460:0034:0000:0980", "2001:0000:0000:0000:2460:3400:0000:9800", "2001:0000:0000:0000:0000:2460:0034:0980"], "c": [2], "why": "Una IPv6 tiene 8 grupos. Acá hay 5 escritos, así que «::» reemplaza 3 grupos de ceros. Además se completan los ceros a la izquierda de cada grupo: 34 → 0034 y 980 → 0980. Ojo: 2001:…:2460:3400:0000:9800 completa los ceros a la derecha; los ceros omitidos siempre son los de la izquierda.", "src": "Forms PDF 1 (preguntero web)"},
{"b": "t10", "pr": false, "q": "¿Cuál debe ser el prefijo de una dirección IPv6 que se usa en un enlace sencillo y nunca debe ser enrutada? Ayuda: se usa para autoconfiguración, descubrimiento de vecinos y en redes sin router.", "o": ["::1", "fe80", "ff00", "2001"], "c": [1], "why": "Las direcciones de enlace local empiezan con fe80 (fe80::/10). Toda interfaz IPv6 tiene una; sirven solo dentro del enlace y los routers no las reenvían. Ojo: ::1 tampoco sale del equipo, pero es el loopback: no sirve para hablar con los vecinos del enlace.", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t10", "pr": false, "q": "¿El tráfico hacia cuáles de estas direcciones IPv6 de destino no será reenviado por el router fuera de su enlace local? (elegí tres)", "o": ["fe80::1", "2001:0410::fe80", "fe90::1:2:3:4", "2001:a:b:c::1", "fe80::abcd:e:f:1234"], "c": [0, 2, 4], "why": "Las de enlace local son fe80::/10: solo los primeros 10 bits están fijos, así que el primer grupo va de fe80 a febf. fe90 también cae en ese rango. Ojo: 2001:0410::fe80 termina en fe80, pero lo que cuenta es el comienzo: es una dirección global.", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t10", "pr": false, "q": "¿Cuáles de los siguientes son tipos de direcciones IPv6 según la RFC 4291? (elegí tres)", "o": ["Unicast", "Dual stack", "Broadcast", "Multicast", "Anycast"], "c": [0, 3, 4], "why": "La RFC 4291 define unicast (a uno), multicast (a un grupo) y anycast (al más cercano de un grupo), además de loopback y de enlace local. IPv6 reemplaza el broadcast por multicast. Ojo: Dual stack no es un tipo de dirección: es usar IPv4 e IPv6 a la vez en un mismo equipo.", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t10", "pr": false, "q": "¿Cuáles de las siguientes se pueden considerar capacidades mejoradas de IPv6 respecto de IPv4? (elegí dos)", "o": ["Simplificación del formato de la cabecera (tamaño fijo)", "Capacidades de direccionamiento extendidas", "Mayor fiabilidad en la transmisión de datagramas", "Tamaño fijo de los datagramas (mensajes de usuario)", "Implementación de circuitos virtuales"], "c": [0, 1], "why": "IPv6 pasa de 32 a 128 bits de dirección y usa una cabecera base de tamaño fijo, más simple de procesar. Sigue siendo un servicio de datagramas: no garantiza entrega ni arma circuitos. Ojo: El tamaño fijo es el de la cabecera, no el de los datagramas: la carga útil sigue siendo variable.", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t10", "pr": false, "q": "¿Cuáles de los siguientes campos están presentes en la cabecera del datagrama IPv6 según la RFC 2460? (elegí tres)", "o": ["Suma de comprobación", "Próxima cabecera", "Etiqueta de flujo", "TTL", "Límite de saltos"], "c": [1, 2, 4], "why": "La cabecera IPv6 tiene versión, clase de tráfico, etiqueta de flujo, longitud de carga útil, próxima cabecera, límite de saltos y las dos direcciones. Límite de saltos reemplaza al TTL y la suma de comprobación se eliminó. Ojo: TTL cumple la misma función que límite de saltos, pero con ese nombre es el campo de IPv4.", "src": "UV 2020 (revisiones) (preguntero web)"},
{"b": "t10", "pr": false, "q": "La cabecera IPv6:", "o": ["Incluye una suma de verificación que cada router recalcula", "Tiene más campos que la cabecera IPv4", "Permite un procesamiento más rápido en los routers", "Incluye campos de fragmentación que revisa cada router", "Tiene longitud variable según las opciones que lleve"], "c": [2], "why": "La cabecera base tiene tamaño fijo y menos campos: sin suma de verificación ni fragmentación en el camino. El router lee siempre la misma estructura y la procesa más rápido. Ojo: Las opciones van en cabeceras de extensión aparte: la cabecera base siempre mide 40 bytes.", "src": "Forms PDF 3 (preguntero web)"},
{"b": "t10", "pr": false, "q": "Sobre la cabecera IPv6, ¿qué afirmaciones son correctas? (elegí tres)", "o": ["Tiene menos campos que la cabecera IPv4", "Su longitud es fija", "Tiene un campo TTL que se decrementa en cada router", "Tiene un campo de suma de verificación de la cabecera", "Elimina los campos de fragmentación"], "c": [0, 1, 4], "why": "IPv6 simplificó la cabecera: 8 campos y 40 bytes fijos. Sacó la suma de verificación y los campos de fragmentación; si hace falta fragmentar, lo hace el origen con una cabecera de extensión. Ojo: La idea del TTL sigue, pero en IPv6 el campo se llama límite de saltos.", "src": "Forms PDF 1 (preguntero web)"},
{"b": "t10", "pr": false, "q": "Una PC quiere intercambiar datos, usando IPv6, con otra computadora ubicada en otro país. ¿Qué tipo de dirección necesita?", "o": ["Unicast global", "Loopback (::1)", "De enlace local (fe80::/10)", "Broadcast", "Multicast"], "c": [0], "why": "Las direcciones globales son las únicas unicast IPv6 que se enrutan por Internet, como las públicas en IPv4. Ojo: La de enlace local la tiene toda interfaz, pero no pasa del router: no llega a otro país.", "src": "Forms PDF 1 (preguntero web)"},
{"b": "t10", "pr": false, "q": "Hacés un ping a ::1 y responde bien. ¿Qué significa?", "o": ["Que el servidor DNS responde", "Que el cable de red y el switch funcionan", "Que la PC tiene salida a Internet por IPv6", "Que TCP/IP está bien instalado en la PC", "Que hay conectividad con la puerta de enlace"], "c": [3], "why": "::1 es la dirección de loopback: el paquete no sale de la PC, vuelve por dentro. Si responde, la pila de protocolos está instalada y funciona, pero no prueba nada de la red. Ojo: No prueba la puerta de enlace: el ping a ::1 ni siquiera usa la placa de red.", "src": "Forms PDF 3 (preguntero web)"},
{"b": "t10", "pr": true, "q": "Para la siguiente topología de red, determinar las direcciones IP que podrían usarse para satisfacer los requisitos de las direcciones de host en la subred de RIO CUARTO", "o": ["192.168.16.130", "192.168.16.131", "192.168.16.22"], "filas": ["PC 1 RC", "PC 3 RC", "PC 2 RC"], "c": [[0, 1], [0, 1], [0, 1]], "img": "fig_04", "why": "Con VLSM se asigna primero la subred más grande: Córdoba (120 hosts) 192.168.16.0/25, Río Cuarto (60 hosts) 192.168.16.128/26, con hosts de .129 a .190 (.129 queda para la puerta de enlace). Entonces .130 y .131 sirven para PC de Río Cuarto, y .22 no, porque cae en la subred de Córdoba.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t10", "pr": false, "q": "Cual de las siguientes afirmaciones es correcta sobre el direccionamiento IPv4", "o": ["Se definieron 255 redes clase C para direccionamiento privado", "Se definieron 255 redes clase B para direccionamiento privado", "Se definieron 16 redes clase B para direccionamiento público", "Se definió una única dirección de red clase A para direccionamiento público", "Se definieron 10 redes clase A para direccionamiento privado"], "c": [2], "why": "El RFC 1918 reservó 1 red clase A (10.0.0.0), 16 redes clase B (172.16.0.0 a 172.31.0.0) y 256 redes clase C (192.168.0.0 a 192.168.255.0), todas para direccionamiento privado. La única opción con el número correcto es «16 redes clase B», aunque dice «público»: ninguna opción es exacta.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t10", "pr": true, "q": "Para la siguiente topología de red, determinar las direcciones IP que podrían usarse para satisfacen los requisitos de direcciones de host en la subred de Villa María", "o": ["192.168.16.226", "192.168.16.227", "192.168.16.238"], "filas": ["PC 2 VM", "PC 3 VM", "PC 1 VM"], "c": [1, 2, 0], "img": "fig_04", "why": "Villa María necesita 20 hosts, así que lleva una /27 (30 hosts). La UV da como correctas PC 1 → .226, PC 2 → .227 y PC 3 → .238, que son hosts válidos de 192.168.16.224/27 (si los enlaces WAN /30 se asignan antes que Villa María, la /27 libre siguiente es .224). Si Villa María estuviera en .192/27 (puerta de enlace .193), sus hosts irían de .193 a .222 y estas IP no servirían.", "nota": "Respuesta discutida: en las fuentes no hay acuerdo total. Leé la explicación.", "src": "Forms preguntero 1.er parcial (preguntero web)"},
{"b": "t10", "pr": false, "q": "Afirmaciones sobre IPv4: ¿cuál es correcta?", "o": ["16 redes clase B direcciones públicas", "256 redes clase B direcciones públicas", "10 redes clase A direcciones privadas", "256 redes clase C direcciones privadas", "Se define una nueva dirección de red clase A para dirección pública"], "c": [3], "why": "El RFC 1918 reserva como privadas 1 red clase A (10.0.0.0), 16 redes clase B (172.16.0.0 a 172.31.0.0) y 256 redes clase C (192.168.0.0 a 192.168.255.0). Ojo: las 16 de clase B son PRIVADAS, no públicas, y la privada de clase A es una sola (la 10).", "src": "Lista que pasaste (23/11) (preguntero web)"},
{"b": "t10", "q": "¿Cuál de los siguientes describe el prefijo de subred de una dirección IPv6 (unicast global típica)?", "o": ["/48", "/64", "/16", "/32", "/128"], "c": [1], "why": "En IPv6 la subred suele ser /64: 64 bits de prefijo (global + subred) y 64 de identificador de interfaz.", "src": "Revisión en clase del 1er parcial (2020)", "pr": false},
{"b": "t10", "q": "Indique cuáles de los siguientes son tipos de direcciones IPv6 según la RFC 4291:", "o": ["Anycast", "Dual stack", "De enlace local", "APIPA", "Unicast", "Loopback", "Multicast", "Broadcast"], "c": [0, 2, 4, 5, 6], "why": "IPv6 tiene unicast (global, enlace local, loopback ::1...), multicast y anycast. NO existe broadcast en IPv6.", "src": "Moodle 1er Parcial 4K4 (2020)", "pr": false},
{"b": "t10", "q": "Qué tipo de dirección IPv6 permite conectividad en Internet:", "o": ["Broadcast", "Multicast", "Global", "Documentación", "Link local"], "c": [2], "why": "La unicast global (2000::/3) es la enrutable en Internet. Link local (fe80) nunca se enruta.", "src": "Revisión en clase del 1er parcial (2020)", "pr": false}
];
